struct Vec3 {
    // Rotation vectors use radians; rho and t use the same length unit.
    double x{}, y{}, z{};
};

Vec3 operator+(Vec3 a, Vec3 b) { return {a.x+b.x, a.y+b.y, a.z+b.z}; }
Vec3 operator-(Vec3 a, Vec3 b) { return {a.x-b.x, a.y-b.y, a.z-b.z}; }
Vec3 operator*(double s, Vec3 v) { return {s*v.x, s*v.y, s*v.z}; }
double dot(Vec3 a, Vec3 b) { return a.x*b.x + a.y*b.y + a.z*b.z; }
double norm(Vec3 v) { return std::sqrt(dot(v,v)); }

struct Mat3 {
    // Row-major storage; multiplication consistently treats vectors as columns.
    std::array<std::array<double,3>,3> a{};
};

Mat3 identity() {
    // Zero initialization supplies off-diagonal zeros; set the identity diagonal.
    Mat3 M{};
    for (int i=0;i<3;++i) M.a[i][i]=1.0;
    return M;
}
Mat3 operator+(Mat3 A, Mat3 B) {
    Mat3 C{};
    for(int r=0;r<3;++r) for(int c=0;c<3;++c) C.a[r][c]=A.a[r][c]+B.a[r][c];
    return C;
}
Mat3 operator-(Mat3 A, Mat3 B) {
    Mat3 C{};
    for(int r=0;r<3;++r) for(int c=0;c<3;++c) C.a[r][c]=A.a[r][c]-B.a[r][c];
    return C;
}
Mat3 operator*(double s, Mat3 A) {
    for(auto& row:A.a) for(double& v:row) v*=s;
    return A;
}
Mat3 operator*(Mat3 A, Mat3 B) {
    // Standard row-by-column composition; k sums the shared dimension.
    Mat3 C{};
    for(int r=0;r<3;++r)
        for(int c=0;c<3;++c)
            for(int k=0;k<3;++k)
                C.a[r][c]+=A.a[r][k]*B.a[k][c];
    return C;
}
Vec3 operator*(Mat3 A, Vec3 v) {
    return {
        A.a[0][0]*v.x + A.a[0][1]*v.y + A.a[0][2]*v.z,
        A.a[1][0]*v.x + A.a[1][1]*v.y + A.a[1][2]*v.z,
        A.a[2][0]*v.x + A.a[2][1]*v.y + A.a[2][2]*v.z
    };
}
Mat3 transpose(Mat3 A) {
    Mat3 T{};
    for(int r=0;r<3;++r) for(int c=0;c<3;++c) T.a[r][c]=A.a[c][r];
    return T;
}
double trace(Mat3 A) { return A.a[0][0]+A.a[1][1]+A.a[2][2]; }

Mat3 hat(Vec3 w) {
    // hat(w) is skew-symmetric and maps v to the cross product w cross v.
    Mat3 W{};
    W.a[0][1] = -w.z;
    W.a[0][2] =  w.y;
    W.a[1][0] =  w.z;
    W.a[1][2] = -w.x;
    W.a[2][0] = -w.y;
    W.a[2][1] =  w.x;
    return W;
}
Vec3 vee(Mat3 W) {
    // Read the three independent skew entries, inverse to hat() on skew matrices.
    return {W.a[2][1], W.a[0][2], W.a[1][0]};
}

Mat3 so3_exp(Vec3 w) {
    // Rodrigues' formula evaluates exp(hat(w)); theta is measured in radians.
    const double theta=norm(w);
    const Mat3 W=hat(w);
    const Mat3 W2=W*W;
    if(theta < 1e-8) {
        // The direct fractions cancel near zero; use their limiting series.
        return identity() + W + 0.5*W2;
    }
    const double A=std::sin(theta)/theta;
    const double B=(1.0-std::cos(theta))/(theta*theta);
    return identity() + A*W + B*W2;
}

Vec3 so3_log(Mat3 R) {
    // Precondition: R is a valid proper rotation. This compact witness does
    // not project or repair malformed matrices before applying the log.
    // Trace yields cos(theta); clamp roundoff into acos's valid domain [-1,1].
    const double cos_theta=std::clamp((trace(R)-1.0)*0.5,-1.0,1.0);
    const double theta=std::acos(cos_theta);
    if(theta < 1e-8) {
        // The antisymmetric part is 2*hat(w) to first order near identity.
        return vee(0.5*(R-transpose(R)));
    }
    // The principal logarithm has a delicate axis branch near pi; reject that
    // region rather than divide by a nearly zero sin(theta) and fake support.
    if (std::abs(std::numbers::pi-theta) <= 1e-5)
        throw std::domain_error("compact SO(3) log witness does not support theta near pi");
    return vee((theta/(2.0*std::sin(theta)))*(R-transpose(R)));
}

Mat3 left_jacobian_so3(Vec3 w) {
    // V maps tangent translation rho to the finite transform translation t.
    const double theta=norm(w);
    const Mat3 W=hat(w);
    const Mat3 W2=W*W;
    if(theta < 1e-8) {
        // Taylor limit avoids subtracting nearly equal trigonometric values.
        return identity() + 0.5*W + (1.0/6.0)*W2;
    }
    const double t2=theta*theta, t3=t2*theta;
    return identity()
         + ((1.0-std::cos(theta))/t2)*W
         + ((theta-std::sin(theta))/t3)*W2;
}

Mat3 left_jacobian_so3_inverse(Vec3 w) {
    // Invert V to recover rho after the logarithm has recovered omega.
    const double theta=norm(w);
    const Mat3 W=hat(w);
    const Mat3 W2=W*W;
    if(theta < 1e-8) {
        // Use the inverse series because the closed-form coefficient is fragile.
        return identity() - 0.5*W + (1.0/12.0)*W2;
    }
    const double s=std::sin(theta), c=std::cos(theta);
    const double coeff=1.0/(theta*theta) - (1.0+c)/(2.0*theta*s);
    return identity() - 0.5*W + coeff*W2;
}

struct SE3 {
    // This transform maps a point p to R*p + t.
    Mat3 R;
    Vec3 t;
};

SE3 se3_exp(Vec3 omega, Vec3 rho) {
    // The group exponential couples translation to rotation through V(omega).
    const Mat3 R=so3_exp(omega);
    const Mat3 V=left_jacobian_so3(omega);
    return {R, V*rho};
}

std::pair<Vec3,Vec3> se3_log(SE3 T) {
    // Assume T contains a valid SE(3) rotation. Rotation is recovered first
    // because its Jacobian determines translation rho; near-pi input throws.
    const Vec3 omega=so3_log(T.R);
    const Mat3 Vinv=left_jacobian_so3_inverse(omega);
    return {omega, Vinv*T.t};
}

bool near(double a,double b,double eps=1e-9){ return std::abs(a-b)<=eps; }
bool near(Vec3 a,Vec3 b,double eps=1e-9){
    return near(a.x,b.x,eps)&&near(a.y,b.y,eps)&&near(a.z,b.z,eps);
}
bool near(Mat3 A,Mat3 B,double eps=1e-9){
    for(int r=0;r<3;++r) for(int c=0;c<3;++c)
        if(!near(A.a[r][c],B.a[r][c],eps)) return false;
    return true;
}

void require(bool condition, const char* message) {
    // Unlike assert, these checks remain active in optimized NDEBUG builds.
    if (!condition) throw std::runtime_error(message);
}

int main() {
    {
        // Ordinary-angle round trip checks both the recovered twist and SO(3) shape.
        const Vec3 w{0.2,-0.3,0.1};
        const Mat3 R=so3_exp(w);
        require(near(transpose(R)*R, identity(), 1e-10), "R must remain orthogonal");
        require(near(so3_log(R), w, 1e-10), "ordinary SO(3) exp/log round trip");
    }
    {
        // Select the small-angle Taylor branch explicitly.
        const Vec3 w{1e-10,-2e-10,3e-10};
        const Mat3 R=so3_exp(w);
        require(near(so3_log(R), w, 1e-9), "small-angle SO(3) exp/log round trip");
    }
    {
        // Both angular and translational tangent coordinates round-trip.
        const Vec3 omega{0.25,-0.15,0.05};
        const Vec3 rho{1.2,-0.4,0.7};
        const SE3 T=se3_exp(omega,rho);
        const auto [omega2,rho2]=se3_log(T);
        require(near(omega2,omega,1e-10), "SE(3) rotational coordinate round trip");
        require(near(rho2,rho,1e-10), "SE(3) translational coordinate round trip");
    }
    {
        // A nonzero omega makes t differ from rho, exposing the coupling.
        // Translation and rotation are coupled by V(omega): t is not generally rho.
        const Vec3 omega{0.0,0.0,0.6};
        const Vec3 rho{1.0,0.0,0.0};
        const SE3 T=se3_exp(omega,rho);
        require(!near(T.t,rho,1e-6), "finite rigid motion must expose V(omega) translation coupling");
        const auto [w2,r2]=se3_log(T);
        require(near(w2,omega,1e-10), "coupled example rotational round trip");
        require(near(r2,rho,1e-10), "coupled example translational round trip");
    }
    {
        // The compact logarithm promises to reject its unsupported near-pi
        // branch before its sin(theta) denominator becomes numerically unsafe.
        const Vec3 near_pi{std::numbers::pi - 5e-6, 0.0, 0.0};
        bool rejected = false;
        try {
            (void)so3_log(so3_exp(near_pi));
        } catch (const std::domain_error&) {
            rejected = true;
        }
        require(rejected, "near-pi logarithm must take its documented rejection branch");
    }
    std::cout << "se3 exp/log: 5 suites PASS\n";
}

// Current state:
Vec2 x;
double currentValue = objective(x);

// Calculate the exact supplied analytical gradient.
const Vec2 g = gradient(x);

// Ensure the gradient is finite before using it.
if (!finite(g))
    return numericalFailure;

// For an unconstrained smooth objective, the negative
// gradient is a descending direction unless g == 0.
const Vec2 direction = -1.0 * g;

// Armijo backtracking searches for an acceptable step.
double alpha = 1.0;

while (true) {
    Vec2 candidate = x + alpha * direction;

    // The actual objective must satisfy sufficient decrease.
    if (objective(candidate) <= currentValue
        + 1e-4 * alpha * dot(g, direction)) {
        x = candidate;
        break;
    }

    alpha *= 0.5;
}

#include <algorithm>
#include <cassert>
#include <cmath>
#include <iomanip>
#include <iostream>
#include <limits>

namespace {

bool close(double a, double b, double tolerance) {
    return std::abs(a - b) <= tolerance;
}

double trapezoid(double a, double b, int n) {
    assert(n > 0);
    const double h = (b - a) / n;
    double sum = 0.5 * (std::exp(a) + std::exp(b));
    for (int i = 1; i < n; ++i)
        sum += std::exp(a + i * h);
    return h * sum;
}

double simpson(double a, double b, int n) {
    assert(n > 0 && n % 2 == 0);
    const double h = (b - a) / n;
    double sum = std::exp(a) + std::exp(b);
    for (int i = 1; i < n; ++i)
        sum += (i % 2 == 0 ? 2.0 : 4.0) * std::exp(a + i * h);
    return h * sum / 3.0;
}

double centralDerivative(double (*f)(double), double x, double h) {
    return (f(x + h) - f(x - h)) / (2.0 * h);
}

double sine(double x) { return std::sin(x); }

double eulerDecay(double h, int steps) {
    double y = 1.0;
    for (int i = 0; i < steps; ++i)
        y += h * (-2.0 * y);
    return y;
}

double rk4Decay(double h, int steps) {
    double y = 1.0;
    for (int i = 0; i < steps; ++i) {
        const double k1 = -2.0 * y;
        const double k2 = -2.0 * (y + 0.5 * h * k1);
        const double k3 = -2.0 * (y + 0.5 * h * k2);
        const double k4 = -2.0 * (y + h * k3);
        y += h * (k1 + 2.0 * k2 + 2.0 * k3 + k4) / 6.0;
    }
    return y;
}

struct State { double q; double p; };

double energy(State s) { return 0.5 * (s.q * s.q + s.p * s.p); }

State explicitEulerOscillator(State s, double h) {
    return {s.q + h * s.p, s.p - h * s.q};
}

State semiImplicitEulerOscillator(State s, double h) {
    const double qNext = s.q + h * s.p;
    const double pNext = s.p - h * qNext;
    return {qNext, pNext};
}

double logCosh(double x) {
    const double ax = std::abs(x);
    return ax + std::log1p(std::exp(-2.0 * ax)) - std::log(2.0);
}

double firstArmijoNewtonStep(double x, int& backtracks) {
    const double value = logCosh(x);
    const double gradient = std::tanh(x);
    const double hessian = 1.0 / std::pow(std::cosh(x), 2.0);
    assert(std::isfinite(value) && hessian > 0.0);
    const double direction = -gradient / hessian;
    assert(gradient * direction < 0.0);

    // A deliberately conservative valid Armijo constant makes the first
    // accepted dyadic trial easy to inspect in this teaching example.
    constexpr double c1 = 0.5;
    double alpha = 1.0;
    backtracks = 0;
    for (int trial = 0; trial < 64; ++trial) {
        const double candidate = x + alpha * direction;
        if (std::isfinite(candidate)
            && logCosh(candidate) <= value + c1 * alpha * gradient * direction)
            return alpha;
        alpha *= 0.5;
        ++backtracks;
    }
    return 0.0;
}
} // namespace

int main() {
    std::cout << std::setprecision(12);

    // Integrate exp(x) on [0,1]; the exact answer is e - 1.
    constexpr int n = 100;
    const double exactIntegral = std::exp(1.0) - 1.0;
    const double trap = trapezoid(0.0, 1.0, n);
    const double simp = simpson(0.0, 1.0, n);
    assert(std::abs(trap - exactIntegral) < 1.5e-5);
    assert(std::abs(simp - exactIntegral) < 1.0e-9);
    assert(std::abs(simp - exactIntegral) < std::abs(trap - exactIntegral));
    std::cout << "quadrature exact=" << exactIntegral << " trapezoid=" << trap
              << " Simpson=" << simp << '\n';

    // Check a numerical derivative against an independent analytic value.
    constexpr double x = 0.7;
    constexpr double hDiff = 1.0e-4;
    const double fd = centralDerivative(sine, x, hDiff);
    assert(std::abs(fd - std::cos(x)) < 1.0e-8);
    std::cout << "central derivative=" << fd << " exact=" << std::cos(x) << '\n';

    // Solve y'=-2y from y(0)=1 to t=1 with h=0.001.
    constexpr int odeSteps = 1000;
    constexpr double hOde = 1.0 / odeSteps;
    const double exactDecay = std::exp(-2.0);
    const double euler = eulerDecay(hOde, odeSteps);
    const double rk4 = rk4Decay(hOde, odeSteps);
    assert(std::abs(euler - exactDecay) < 3.0e-4);
    assert(std::abs(euler - exactDecay) > 1.0e-5);
    assert(std::abs(rk4 - exactDecay) < 1.0e-12);
    assert(std::abs(rk4 - exactDecay) < std::abs(euler - exactDecay));
    std::cout << "decay exact=" << exactDecay << " Euler=" << euler
              << " RK4=" << rk4 << '\n';

    // Compare energy behavior for q'=p, p'=-q over t=100.
    constexpr double hOsc = 0.1;
    constexpr int oscSteps = 1000;
    State explicitState{1.0, 0.0};
    State semiState{1.0, 0.0};
    double explicitFinalEnergy = energy(explicitState);
    double semiMinEnergy = energy(semiState);
    double semiMaxEnergy = energy(semiState);
    for (int i = 0; i < oscSteps; ++i) {
        explicitState = explicitEulerOscillator(explicitState, hOsc);
        semiState = semiImplicitEulerOscillator(semiState, hOsc);
        explicitFinalEnergy = energy(explicitState);
        semiMinEnergy = std::min(semiMinEnergy, energy(semiState));
        semiMaxEnergy = std::max(semiMaxEnergy, energy(semiState));
    }
    assert(explicitFinalEnergy > 100.0);
    assert(semiMinEnergy > 0.46 && semiMaxEnergy < 0.54);
    assert(semiMaxEnergy > semiMinEnergy);
    std::cout << "oscillator E0=0.5 explicit E(100)=" << explicitFinalEnergy
              << " semi-implicit range=[" << semiMinEnergy << ',' << semiMaxEnergy
              << "] (bounded here, not exact)\n";

    // A safeguarded Newton step for f(x)=log(cosh(x)), starting at x=3.
    int backtracks = 0;
    const double alpha = firstArmijoNewtonStep(3.0, backtracks);
    assert(close(alpha, 1.0 / 32.0, 0.0));
    assert(backtracks == 5);
    const double gradientAtStart = std::tanh(3.0);
    const double hessianAtStart = 1.0 / std::pow(std::cosh(3.0), 2.0);
    const double newtonDirection = -gradientAtStart / hessianAtStart;
    const double nextX = 3.0 + alpha * newtonDirection;
    assert(logCosh(nextX) < logCosh(3.0));
    std::cout << "Newton x0=3 alpha=" << alpha << " backtracks=" << backtracks
              << " x1=" << nextX << " f1=" << logCosh(nextX) << '\n';

    std::cout << "all quantitative assertions passed\n";
}

struct KahanSum {
    double sum = 0.0;
    double correction = 0.0;

    void add(double x) {
        // Compensate for rounding error retained
        // from previous additions.
        const double y = x - correction;

        // Add the corrected contribution.
        const double t = sum + y;

        // Estimate the low-order error introduced
        // by the floating-point addition.
        correction = (t - sum) - y;

        sum = t;
    }
};

struct NeumaierSum {
    double sum = 0.0;
    double correction = 0.0;

    void add(double x) {
        const double t = sum + x;

        if (std::abs(sum) >= std::abs(x)) {
            correction += (sum - t) + x;
        } else {
            correction += (x - t) + sum;
        }

        sum = t;
    }

    [[nodiscard]]
    double value() const {
        return sum + correction;
    }
};

double pairwiseSum(
    const double* data,
    std::size_t count
) {
    if (count == 0)
        return 0.0;

    if (count == 1)
        return data[0];

    const std::size_t middle = count / 2;

    const double left =
        pairwiseSum(data, middle);

    const double right =
        pairwiseSum(data + middle, count - middle);

    return left + right;
}

double lerp(double a, double b, double t) {
    return a + t * (b - a);
}

double lerp(double a, double b, double t) {
    return std::fma(t, b - a, a);
}

double cubicBezier(
    double p0,
    double p1,
    double p2,
    double p3,
    double t
) {
    // First interpolation layer.
    const double a = std::lerp(p0, p1, t);
    const double b = std::lerp(p1, p2, t);
    const double c = std::lerp(p2, p3, t);

    // Second layer.
    const double d = std::lerp(a, b, t);
    const double e = std::lerp(b, c, t);

    // Final point.
    return std::lerp(d, e, t);
}

struct LCG32 {
    std::uint32_t state;

    explicit LCG32(std::uint32_t seed)
        : state(seed) {}

    std::uint32_t next() noexcept {
        // Arithmetic intentionally wraps modulo 2^32.
        // This is defined for unsigned integer types.
        state = state * 1664525u + 1013904223u;
        return state;
    }
};

#include <cstdint>

// An avalanche-style 64-bit mixing function.
// It maps one 64-bit input to one scrambled 64-bit output.
//
// A mixer is NOT, by itself, a proof that a collection of
// indexed outputs behaves like independent random variables.
std::uint64_t mix64(std::uint64_t x) noexcept {
    x ^= x >> 30;
    x *= 0xbf58476d1ce4e5b9ULL;

    x ^= x >> 27;
    x *= 0x94d049bb133111ebULL;

    x ^= x >> 31;
    return x;
}

std::uint64_t sample_key(
    std::uint64_t globalSeed,
    std::uint32_t pixelX,
    std::uint32_t pixelY,
    std::uint32_t sampleIndex,
    std::uint32_t dimension
) noexcept {
    std::uint64_t key = mix64(globalSeed);

    // Mix each logical coordinate into the accumulated key.
    // Different dimensions and pixels obtain different inputs.
    key = mix64(key ^ pixelX);
    key = mix64(key ^ pixelY);
    key = mix64(key ^ sampleIndex);
    key = mix64(key ^ dimension);

    return key;
}

struct DirectionSample {
    Vec3 direction;

    // Probability density with respect to solid angle.
    // Units: inverse steradians.
    double pdfSolidAngle;
};

double sampleIncreasingLinearPdf(double u) {
    // Target: p(x) = 2*x on [0,1].
    // Its CDF is x*x; [[Inverse, rejection, and importance sampling|inverse CDF]] is sqrt(u).
    if (!std::isfinite(u) || u < 0.0 || u >= 1.0)
        throw std::domain_error("Expected [0,1) sample");

    return std::sqrt(u);
}

double sampleIncreasingLinearPdf(double u) {
    // Target: p(x) = 2*x on [0,1].
    // Its CDF is x*x; inverse CDF is sqrt(u).
    if (u < 0.0 || u >= 1.0)
        throw std::domain_error("Expected [0,1) sample");

    return std::sqrt(u);
}

double sampleExponential(double u, double lambda) {
    if (!(lambda > 0.0) || !std::isfinite(lambda))
        throw std::domain_error("Invalid rate");

    if (!(u >= 0.0 && u < 1.0))
        throw std::domain_error("Invalid uniform input");

    // log1p(-u) accurately computes log(1-u),
    // particularly for small u.
    return -std::log1p(-u) / lambda;
}

double onlineMean(std::span<const double> samples) {
    if (samples.empty())
        throw std::invalid_argument("No samples");

    double mean = 0.0;
    std::size_t count = 0;

    for (const double x : samples) {
        ++count;

        // Move the current mean toward the new sample.
        // The movement shrinks as the sample count grows.
        mean += (x - mean) /
                static_cast<double>(count);
    }

    return mean;
}

struct Welford {
    std::size_t count = 0;

    double mean = 0.0;

    // Sum of squared deviations from the current mean.
    double m2 = 0.0;

    void add(double x) {
        if (!std::isfinite(x))
            throw std::domain_error("Nonfinite sample");

        ++count;

        const double delta = x - mean;

        mean += delta / static_cast<double>(count);

        const double delta2 = x - mean;

        // Corrected centred sum-of-squares update.
        m2 += delta * delta2;
    }

    double sampleVariance() const {
        if (count < 2)
            throw std::domain_error("Need at least two samples");

        // Unbiased sample variance under IID assumptions.
        return m2 / static_cast<double>(count - 1);
    }

    double populationVariance() const {
        if (count == 0)
            throw std::domain_error("No samples");

        return m2 / static_cast<double>(count);
    }
};

struct Normal {
    double mu;
    double sigma;

    Normal(double mean, double sd)
        : mu(mean), sigma(sd) {

        // A valid nonsingular Gaussian requires sigma > 0.
        // A NaN or infinite parameter is not accepted.
        if (!std::isfinite(mu) ||
            !std::isfinite(sigma) ||
            !(sigma > 0.0)) {

            throw std::domain_error(
                "Invalid normal distribution parameters"
            );
        }
    }

    [[nodiscard]]
    double pdf(double x) const {
        const double z = (x - mu) / sigma;

        return std::exp(-0.5 * z * z) /
               (sigma * std::sqrt(2.0 * std::numbers::pi));
    }

    [[nodiscard]]
    double cdf(double x) const {
        const double z =
            (x - mu) /
            (sigma * std::numbers::sqrt2);

        // erfc avoids cancellation from 1 + erf(z)
        // when z is far into the negative tail.
        return 0.5 * std::erfc(-z);
    }

    [[nodiscard]]
    double survival(double x) const {
        const double z =
            (x - mu) /
            (sigma * std::numbers::sqrt2);

        // Direct upper-tail calculation avoids 1 - CDF(x)
        // when CDF(x) is extremely close to one.
        return 0.5 * std::erfc(z);
    }
};

[[nodiscard]]
double binomial_pmf(
    unsigned n,
    unsigned k,
    double p
) {
    if (!std::isfinite(p) ||
        p < 0.0 || p > 1.0) {
        throw std::domain_error("Invalid probability");
    }

    if (k > n)
        return 0.0;

    // Avoid log(0) and correctly handle deterministic cases.
    if (p == 0.0)
        return k == 0 ? 1.0 : 0.0;

    if (p == 1.0)
        return k == n ? 1.0 : 0.0;

    // ln(n choose k)
    const double logChoose =
        std::lgamma(static_cast<double>(n) + 1.0)
      - std::lgamma(static_cast<double>(k) + 1.0)
      - std::lgamma(static_cast<double>(n - k) + 1.0);

    // Compute log probability first.
    // log1p(-p) is useful when p is small.
    const double logProbability =
        logChoose +
        static_cast<double>(k) * std::log(p) +
        static_cast<double>(n - k) * std::log1p(-p);

    return std::exp(logProbability);
}

[[nodiscard]]
double poisson_pmf(unsigned k, double lambda) {
    if (!std::isfinite(lambda) || lambda < 0.0)
        throw std::domain_error("Invalid Poisson mean");

    if (lambda == 0.0)
        return k == 0 ? 1.0 : 0.0;

    const double logProbability =
        static_cast<double>(k) * std::log(lambda)
        - lambda
        - std::lgamma(static_cast<double>(k) + 1.0);

    return std::exp(logProbability);
}

using Vec2 = std::array<double, 2>;

struct Mat2 {
    double a00, a01;
    double a10, a11;
};

struct Normal2D {
    Vec2 mu;
    Mat2 cov;

    // Lower-triangular Cholesky entries:
    //
    // L = [l00   0 ]
    //     [l10  l11]
    //
    // Sigma = L * transpose(L)
    double l00;
    double l10;
    double l11;

    double logDet;

    Normal2D(Vec2 mean, Mat2 sigma)
        : mu(mean), cov(sigma) {

        // The complete source first checks symmetry
        // and positive semidefiniteness.
        if (!is_psd(cov))
            throw std::domain_error("Invalid covariance");

        // The ordinary 2D density requires STRICT
        // positive definiteness, not merely PSD.
        if (!(cov.a00 > 0.0))
            throw std::domain_error("Singular covariance");

        l00 = std::sqrt(cov.a00);
        l10 = cov.a10 / l00;

        // Schur complement for the second pivot.
        const double schur =
            cov.a11 - l10 * l10;

        if (!(schur > 0.0))
            throw std::domain_error("Singular covariance");

        l11 = std::sqrt(schur);

        logDet =
            2.0 * (std::log(l00) + std::log(l11));
    }

    [[nodiscard]]
    double log_pdf(Vec2 x) const {
        // Forward substitution:
        // Solve L*y = (x-mu).
        const double y0 =
            (x[0] - mu[0]) / l00;

        const double y1 =
            ((x[1] - mu[1]) - l10 * y0) / l11;

        // This is the squared Mahalanobis distance.
        const double mahalanobisSquared =
            y0 * y0 + y1 * y1;

        return
            -std::log(2.0 * std::numbers::pi)
            -0.5 * logDet
            -0.5 * mahalanobisSquared;
    }
};

struct OnlineCovariance2D {
    std::size_t n = 0;

    std::array<double, 2> mean{0.0, 0.0};

    // Accumulated centered co-moments.
    double s00 = 0.0;
    double s01 = 0.0;
    double s11 = 0.0;

    void add(std::array<double, 2> x) {
        ++n;

        // Difference from OLD mean.
        const double dx0 = x[0] - mean[0];
        const double dx1 = x[1] - mean[1];

        // Update mean.
        mean[0] += dx0 / static_cast<double>(n);
        mean[1] += dx1 / static_cast<double>(n);

        // Cross-products use the NEW mean in the second factor.
        s00 += dx0 * (x[0] - mean[0]);
        s01 += dx0 * (x[1] - mean[1]);
        s11 += dx1 * (x[1] - mean[1]);
    }

    [[nodiscard]]
    Mat2 sampleCovariance() const {
        if (n < 2)
            throw std::domain_error(
                "Need at least two observations"
            );

        const double divisor =
            static_cast<double>(n - 1);

        return {
            s00 / divisor,
            s01 / divisor,
            s01 / divisor,
            s11 / divisor
        };
    }
};

double logsumexp(std::span<const double> logits) {
    if (logits.empty())
        throw std::invalid_argument("No log weights");

    // A production API must also define its policy for
    // NaN, +infinity and all -infinity inputs.
    const double m =
        *std::max_element(logits.begin(), logits.end());

    double sum = 0.0;

    for (const double x : logits) {
        // The largest exponent is zero.
        // Every other finite exponent is negative.
        sum += std::exp(x - m);
    }

    return m + std::log(sum);
}

template<class URBG>
void fisherYates(
    std::span<std::uint32_t> indices,
    URBG& rng
) {
    for (std::size_t i = indices.size(); i > 1; --i) {
        // Uniform among all remaining positions.
        std::uniform_int_distribution<std::size_t> dist(
            0, i - 1
        );

        const std::size_t j = dist(rng);

        std::swap(indices[i - 1], indices[j]);
    }
}

// Mathematics continuous-note C++20 first-contact oracle; code and tested source stay identical.
#include <cmath>
#include <iostream>
#include <optional>
#include <stdexcept>
struct Vec2 { double x{}, y{}; };
struct Disk2 { Vec2 centre{}, velocity{}; double radius{}; };
double dot(Vec2 a, Vec2 b) { return a.x*b.x+a.y*b.y; }

std::optional<double> firstTouch(Disk2 a, Disk2 b, double h) {
    const auto valid = [](Disk2 d) {
        return std::isfinite(d.centre.x)&&std::isfinite(d.centre.y)&&
               std::isfinite(d.velocity.x)&&std::isfinite(d.velocity.y)&&
               std::isfinite(d.radius)&&d.radius>0;
    };
    if (!valid(a)||!valid(b)||!std::isfinite(h)||h<0)
        throw std::invalid_argument("invalid disk or horizon");
    Vec2 p{b.centre.x-a.centre.x,b.centre.y-a.centre.y};
    Vec2 v{b.velocity.x-a.velocity.x,b.velocity.y-a.velocity.y};
    const double R=a.radius+b.radius;
    const double aa=dot(v,v),bb=2*dot(p,v),cc=dot(p,p)-R*R;
    if (!std::isfinite(aa)||!std::isfinite(bb)||!std::isfinite(cc))
        throw std::overflow_error("nonfinite collision coefficients");
    if (cc<0) throw std::domain_error("existing overlap");
    if (cc==0) return 0.0; // Touching, not automatically a new impact.
    if (aa==0||bb>=0) return std::nullopt;
    const double discriminant=std::fma(bb,bb,-4*aa*cc);
    if (!std::isfinite(discriminant))
        throw std::overflow_error("discriminant overflow");
    if (discriminant<0) return std::nullopt;
    const double q=-0.5*(bb-std::sqrt(discriminant));
    if (!(q>0)) return std::nullopt;
    const double t=cc/q;
    if (!std::isfinite(t)||t<0||t>h) return std::nullopt;
    return t;
}
int main() {
    auto near=[](double actual,double expected) {
        if (!std::isfinite(actual)||std::abs(actual-expected)>1e-10)
            throw std::runtime_error("unexpected first-contact time");
    };
    const Disk2 fixed{{0,0},{0,0},1};
    const Disk2 moving{{10,0},{-100,0},1};
    const auto impact=firstTouch(fixed,moving,0.1);
    if (!impact) throw std::runtime_error("fast contact was missed");
    near(*impact,0.08);
    if (firstTouch(fixed,moving,0.05))
        throw std::runtime_error("collision outside horizon was accepted");
    if (firstTouch(fixed,{{10,0},{100,0},1},1.0))
        throw std::runtime_error("separating disks reported impact");
    if (firstTouch(fixed,{{10,0},{0,0},1},1.0))
        throw std::runtime_error("static separated disks reported impact");
    if (firstTouch(fixed,{{10,2.1},{-10,0},1},2.0))
        throw std::runtime_error("geometric near miss reported impact");
    const auto tangent=firstTouch(fixed,{{10,2},{-10,0},1},2.0);
    if (!tangent) throw std::runtime_error("tangency not found");
    near(*tangent,1.0);
    const auto galilean=firstTouch({{0,0},{55,7},1},
                                   {{10,0},{-45,7},1},0.1);
    if (!galilean) throw std::runtime_error("relative motion invariance failed");
    near(*galilean,0.08);
    bool rejected=false;
    try { (void)firstTouch(fixed,{{1,0},{0,0},1},1); }
    catch(const std::domain_error&) { rejected=true; }
    if (!rejected) throw std::runtime_error("initial overlap not rejected");
    rejected=false;
    try { (void)firstTouch(fixed,moving,-1); }
    catch(const std::invalid_argument&) { rejected=true; }
    if (!rejected) throw std::runtime_error("negative time accepted");
    std::cout<<"math first contact: entry, no-hit, tangency, invariance and validation PASS\n";
}

