Vec3 SampleUniformHemisphere(
    float xi1,
    float xi2)
{
    const float y = xi1;

    const float phi =
        2.0f * Pi * xi2;

    const float radius =
        std::sqrt(
            std::max(
                0.0f,
                1.0f - y * y));

    return
    {
        radius * std::cos(phi),
        y,
        radius * std::sin(phi)
    };
}

Vec3 BuildTangent(Vec3 n)
{
    const Vec3 helper =
        std::abs(n.y) < 0.999f
        ? Vec3{0, 1, 0}
        : Vec3{1, 0, 0};

    return Normalize(
        Cross(helper, n));
}

