float PowerHeuristic(
    float pdfA,
    float pdfB)
{
    const float a2 = pdfA * pdfA;
    const float b2 = pdfB * pdfB;

    return
        a2 /
        max(a2 + b2, epsilon);
}

Color TracePath(
    Ray ray,
    RNG& rng)
{
    Color L = Color::Black();

    // Throughput from camera to current vertex.
    Color beta = Color::White();

    bool previousWasDelta = true;

    for (uint32_t bounce = 0;
         bounce < MaxDepth;
         ++bounce)
    {
        const auto hit =
            scene.Intersect(ray);

        if (!hit)
        {
            // Environment radiance reaching this path.
            L += beta *
                 scene.Environment(
                     ray.Direction);
            break;
        }

        const Material& material =
            scene.Material(
                hit->MaterialID);

        // Surface emission.
        L += beta *
             material.Emission;

        // Direct-light next-event estimation would happen here.

        BSDFSample s =
            SampleBSDF(
                material,
                *hit,
                -ray.Direction,
                rng);

        if (!s.Valid ||
            s.Pdf <= 0.0f)
        {
            break;
        }

        const float cosine =
            std::abs(
                Dot(
                    hit->ShadingNormal,
                    s.Wi));

        beta *=
            s.F *
            (cosine / s.Pdf);

        ray =
            SpawnRay(
                *hit,
                s.Wi);

        // Russian roulette after a few bounces...
    }

    return L;
}

struct PixelStatistics
{
    uint64_t count = 0;

    Color mean = Color::Black();
    Color m2   = Color::Black();

    void AddSample(const Color& x)
    {
        ++count;

        const Color delta =
            x - mean;

        mean +=
            delta /
            static_cast<float>(count);

        const Color delta2 =
            x - mean;

        m2 +=
            delta * delta2;
    }

    Color Variance() const
    {
        if (count < 2)
            return Color::Black();

        return
            m2 /
            static_cast<float>(count - 1);
    }

    Color StandardError() const
    {
        if (count < 2)
            return Color::Black();

        return Sqrt(
            Variance() /
            static_cast<float>(count));
    }
};

BSDFSample SampleIdealGlass(
    Vec3 wo,
    Vec3 n,
    float etaI,
    float etaT,
    RNG& rng)
{
    const float cosTheta =
        std::clamp(
            Dot(wo, n),
            0.0f,
            1.0f);

    const float F =
        FresnelDielectric(
            cosTheta,
            etaI,
            etaT);

    const float eta =
        etaI / etaT;

    const auto wt =
        Refract(
            -wo,
            n,
            eta);

    // Total internal reflection.
    if (!wt)
    {
        return
        {
            .Wi = Reflect(-wo, n),
            .Probability = 1.0f,
            .IsDelta = true,
            .IsTransmission = false
        };
    }

    if (Random01(rng) < F)
    {
        return
        {
            .Wi = Reflect(-wo, n),
            .Probability = F,
            .IsDelta = true,
            .IsTransmission = false
        };
    }

    return
    {
        .Wi = *wt,
        .Probability = 1.0f - F,
        .IsDelta = true,
        .IsTransmission = true
    };
}

