Color TracePath(
    const Scene& scene,
    Ray ray,
    RNG& rng)
{
    Color L =
        Color::Black();

    Color beta =
        Color::White();

    float previousBsdfPdf = 0.0f;
    bool previousDelta = true;

    for (uint32_t bounce = 0;
         bounce < MaxDepth;
         ++bounce)
    {
        const auto hit =
            scene.Intersect(ray);

        if (!hit)
        {
            const Color Le =
                scene.SampleEnvironment(
                    ray.Direction);

            if (bounce == 0 ||
                previousDelta)
            {
                L += beta * Le;
            }
            else
            {
                const float lightPdf =
                    scene.EnvironmentPdf(
                        ray.Direction);

                const float w =
                    PowerHeuristic(
                        previousBsdfPdf,
                        lightPdf);

                L +=
                    beta *
                    Le *
                    w;
            }

            break;
        }

        const Material& material =
            scene.Materials[
                hit->MaterialIndex];

        // -----------------------------------------------------
        // Emissive surface hit.
        // -----------------------------------------------------
        if (IsEmitter(material))
        {
            const Color Le =
                material.Emission;

            if (bounce == 0 ||
                previousDelta)
            {
                L += beta * Le;
            }
            else
            {
                const float lightPdf =
                    scene.PdfEmitterHit(
                        ray,
                        *hit);

                const float w =
                    PowerHeuristic(
                        previousBsdfPdf,
                        lightPdf);

                L +=
                    beta *
                    Le *
                    w;
            }
        }

        const Vec3 wo =
            -ray.Direction;

        // -----------------------------------------------------
        // Next-event estimation for non-delta BSDFs.
        // -----------------------------------------------------
        if (!IsPureDelta(material))
        {
            LightSample light =
                scene.SampleLight(
                    *hit,
                    rng);

            if (light.Valid &&
                light.Pdf > 0.0f)
            {
                const float cosTheta =
                    std::max(
                        Dot(
                            hit->ShadingNormal,
                            light.Wi),
                        0.0f);

                if (cosTheta > 0.0f &&
                    !scene.Occluded(
                        SpawnShadowRay(
                            *hit,
                            light.Wi,
                            light.Distance)))
                {
                    const Color f =
                        EvaluateBSDF(
                            material,
                            *hit,
                            wo,
                            light.Wi);

                    const float bsdfPdf =
                        PdfBSDF(
                            material,
                            *hit,
                            wo,
                            light.Wi);

                    const float w =
                        light.IsDelta
                        ? 1.0f
                        : PowerHeuristic(
                            light.Pdf,
                            bsdfPdf);

                    L +=
                        beta *
                        f *
                        light.Radiance *
                        (cosTheta *
                         w /
                         light.Pdf);
                }
            }
        }

        // -----------------------------------------------------
        // Continue path by BSDF sampling.
        // -----------------------------------------------------
        BSDFSample bsdf =
            SampleBSDF(
                material,
                *hit,
                wo,
                rng);

        if (!bsdf.Valid ||
            bsdf.Pdf <= 0.0f)
        {
            break;
        }

        const float cosine =
            bsdf.IsDelta
            ? 1.0f
            : std::abs(
                Dot(
                    hit->ShadingNormal,
                    bsdf.Wi));

        beta *=
            bsdf.F *
            (cosine /
             bsdf.Pdf);

        if (!IsFinite(beta) ||
            MaxComponent(beta) <= 0.0f)
        {
            break;
        }

        previousBsdfPdf =
            bsdf.Pdf;

        previousDelta =
            bsdf.IsDelta;

        ray =
            SpawnRay(
                *hit,
                bsdf.Wi,
                bsdf.IsTransmission);

        // -----------------------------------------------------
        // Russian roulette.
        // -----------------------------------------------------
        if (bounce >= 3)
        {
            const float survival =
                std::clamp(
                    MaxComponent(beta),
                    0.05f,
                    0.95f);

            if (Random01(rng) >
                survival)
            {
                break;
            }

            beta /= survival;
        }
    }

    return L;
}

