    const auto inside=clipSegment({-1,0},{1,0},{0,0},{1,0});
    if (inside.size()!=2 || std::abs(inside[1].x)>1e-12)
        throw std::runtime_error("straddling segment regression failed");
    std::cout<<"clipped endpoint: "<<inside[1].x<<"\n";
}

