ComponentOperations MakeOperations()
{
    return
    {
        .Size = sizeof(T),
        .Alignment = alignof(T),

        .DefaultConstruct =
            [](void* destination)
            {
                std::construct_at(
                    static_cast<T*>(destination));
            },

        .MoveConstruct =
            [](void* destination,
               void* source)
            {
                std::construct_at(
                    static_cast<T*>(destination),
                    std::move(
                        *static_cast<T*>(source)));
