    const float split =
        p.position[node.axis];

    if (query.min[node.axis] <= split)
    {
        rangeSearch(
            node.left,
            query,
            output);
    }

    if (query.max[node.axis] >= split)
    {
        rangeSearch(
            node.right,
            query,
            output);
    }
}

