    try { allmight::run(); }
    catch (const std::exception& error) {
        std::cerr << "asset_container_lab failed: " << error.what() << '\n';
        return 1;
    }
}

// Project AllMight M016 / Parts 251-270, C++20 executable reference.
// Extends the growing asset registry into a read-only query snapshot, typed
// results, ordered searches, deterministic reporting and safe erasure.
// No GPU submission, allocator benchmark or concurrent registry is claimed.
#include <algorithm>
#include <any>
#include <cassert>
#include <cstddef>
#include <cstdint>
#include <deque>
#include <forward_list>
#include <functional>
#include <iostream>
#include <iterator>
#include <list>
#include <numeric>
#include <optional>
#include <ranges>
#include <sstream>
#include <stdexcept>
#include <string>
