    try { allmight::run(); }
    catch (const std::exception& error) {
        std::cerr << "asset_query_algorithm_lab failed: " << error.what() << '\n';
        return 1;
    }
}

// AllMight M017, Parts 271-280: owned snapshot queries, ranges, allocators, PMR.
// C++20; deterministic CPU model, NOT a graphics driver / concurrent registry.
#include <algorithm>
#include <array>
#include <cstddef>
#include <cstdint>
#include <functional>
#include <iostream>
#include <iterator>
#include <limits>
#include <memory>
#include <memory_resource>
#include <numeric>
#include <ranges>
#include <span>
#include <stdexcept>
#include <string>
#include <string_view>
#include <type_traits>
#include <unordered_map>
#include <utility>
#include <vector>

namespace allmight::asset_query {

void require(bool valid, const char* what) {
    if (!valid) throw std::runtime_error(what); // valid even with -DNDEBUG
}

// An owning snapshot is a separate lifetime from the live asset registry.
// Tombstones stay in this example to make a custom forward iterator useful.
struct Row {
    std::string name;
    std::size_t bytes;
    bool live;
};

std::vector<Row> make_snapshot() {
    return {{"brick.mesh", 48, true}, {"retired.tex", 512, false},
            {"sky.tex", 64, true}, {"ui.tex", 16, true},
            {"terrain.mesh", 128, true}, {"rock.mesh", 48, true}};
}

// Custom multi-pass forward iterator. It borrows the Row vector and skips
// tombstones, but does not own the vector or preserve validity on reallocation.
class LiveRowIterator {
    const std::vector<Row>* rows_ = nullptr;
    std::size_t pos_ = 0;

    void skip_dead() noexcept {
        if (!rows_) return;
        while (pos_ < rows_->size() && !(*rows_)[pos_].live) ++pos_;
    }
public:
    using iterator_concept = std::forward_iterator_tag;
    using iterator_category = std::forward_iterator_tag;
    using value_type = Row;
    using difference_type = std::ptrdiff_t;
    using reference = const Row&;

    LiveRowIterator() = default;
    LiveRowIterator(const std::vector<Row>& rows, std::size_t pos)
        : rows_(&rows), pos_(pos) { skip_dead(); }
    reference operator*() const noexcept { return (*rows_)[pos_]; }
    const Row* operator->() const noexcept { return std::addressof(**this); }
    LiveRowIterator& operator++() noexcept { ++pos_; skip_dead(); return *this; }
    LiveRowIterator operator++(int) noexcept { auto old = *this; ++*this; return old; }
    friend bool operator==(const LiveRowIterator&, const LiveRowIterator&) = default;
};
static_assert(std::forward_iterator<LiveRowIterator>);
static_assert(!std::bidirectional_iterator<LiveRowIterator>);
static_assert(!std::contiguous_iterator<LiveRowIterator>);

// begin() and end() are discovered in range-based for's exposition model.
// A range-for keeps its range expression alive for the loop, but a returned
// view or stored iterator still requires explicit owner-lifetime reasoning.
struct LiveRows {
    const std::vector<Row>* owner;
    LiveRowIterator begin() const { return LiveRowIterator{*owner, 0}; }
    LiveRowIterator end() const { return LiveRowIterator{*owner, owner->size()}; }
};
static_assert(std::ranges::forward_range<LiveRows>);

// An illustrative C++ allocator: typed allocate/deallocate must be paired.
// The shared statistics object survives copies/rebinds of the allocator.
struct AllocationStats {
    std::size_t allocations = 0;
    std::size_t deallocations = 0;
    std::size_t allocated_bytes = 0;
};
template<class T>
struct TrackingAllocator {
    using value_type = T;
    std::shared_ptr<AllocationStats> stats;
    TrackingAllocator() : stats(std::make_shared<AllocationStats>()) {}
    explicit TrackingAllocator(std::shared_ptr<AllocationStats> s) : stats(std::move(s)) {}
    template<class U>
    TrackingAllocator(const TrackingAllocator<U>& other) noexcept : stats(other.stats) {}
    T* allocate(std::size_t count) {
        if (count > std::allocator_traits<std::allocator<T>>::max_size(std::allocator<T>{}))
            throw std::bad_array_new_length();
        auto* raw = std::allocator<T>{}.allocate(count);
        ++stats->allocations;
        stats->allocated_bytes += count * sizeof(T);
        return raw;
    }
    void deallocate(T* ptr, std::size_t count) noexcept {
        ++stats->deallocations;
        std::allocator<T>{}.deallocate(ptr, count);
    }
    template<class U> friend struct TrackingAllocator;
    template<class U> bool operator==(const TrackingAllocator<U>& rhs) const noexcept {
        return stats == rhs.stats;
    }
};

// std::pmr moves the allocation-policy choice to runtime. The resource must
// outlive every container and object retaining a pointer to it.
class CountingMemoryResource final : public std::pmr::memory_resource {
    std::pmr::memory_resource* upstream_;
public:
    std::size_t allocated_blocks = 0;
    std::size_t freed_blocks = 0;
    std::size_t allocated_bytes = 0;
    explicit CountingMemoryResource(std::pmr::memory_resource* upstream)
        : upstream_(upstream) {}
private:
    void* do_allocate(std::size_t bytes, std::size_t alignment) override {
        void* ptr = upstream_->allocate(bytes, alignment);
        ++allocated_blocks;
        allocated_bytes += bytes;
        return ptr;
    }
    void do_deallocate(void* ptr, std::size_t bytes, std::size_t alignment) override {
        ++freed_blocks;
        upstream_->deallocate(ptr, bytes, alignment);
    }
    bool do_is_equal(const std::pmr::memory_resource& other) const noexcept override {
        return this == &other;
    }
};

// Function objects and lambdas give equivalent call semantics here, but
// code generation/allocations/capture size need MEASUREMENT, not slogans.
struct AtLeastBytes {
    std::size_t threshold;
    bool operator()(const Row& row) const noexcept { return row.bytes >= threshold; }
};

void run() {
    auto rows = make_snapshot();
    LiveRows live{&rows};
    std::size_t visits = 0;
    std::size_t total = 0;
    for (const Row& row : live) { // range-based for begin/end, not indexing
        ++visits;
        total += row.bytes;
    }
    require(visits == 5 && total == 304, "custom forward iterator skips tombstones");

    // Filter/transform adaptor creation is lazy. We can observe that neither
    // predicate nor transform runs until the range is iterated.
    std::size_t predicate_calls = 0;
    std::size_t projection_calls = 0;
    auto pipeline = std::views::all(rows)
        | std::views::filter([&](const Row& row) {
              ++predicate_calls;
              return row.live && row.bytes >= 48;
          })
        | std::views::transform([&](const Row& row) {
              ++projection_calls;
              return row.name;
          });
    require(predicate_calls == 0 && projection_calls == 0, "views compose lazily");
    std::vector<std::string> names;
    for (const auto& name : pipeline) names.push_back(name);
    require(names == std::vector<std::string>({"brick.mesh", "sky.tex",
                                               "terrain.mesh", "rock.mesh"}),
            "filter and transform produce the correct sequence");
    require(predicate_calls > 0 && projection_calls == 4,
            "predicates/transform execute during traversal");

    // Borrowed means iterators can outlive the range VIEW under its contract;
    // it does not mean the underlying vector's owner is kept alive.
    static_assert(std::ranges::borrowed_range<std::ranges::ref_view<std::vector<Row>>>);
    static_assert(!std::ranges::borrowed_range<std::vector<Row>>);
    static_assert(!std::ranges::borrowed_range<std::ranges::owning_view<std::vector<Row>>>);
    auto owned = std::views::all(make_snapshot()); // owns its vector in the view
    require(std::ranges::distance(owned) == 6, "rvalue vector becomes owning view");

    // A projection is supplied separately from a comparator: ranges::find
    // compares row.name, not the Row object or an allocated name list.
    auto located = std::ranges::find(rows, std::string_view{"sky.tex"}, &Row::name);
    require(located != rows.end() && located->bytes == 64,
            "projected ranges::find locates the named asset");
    auto sorted = rows;
    std::ranges::sort(sorted, std::less<>{}, &Row::bytes);
    require(sorted.front().bytes == 16 && sorted.back().bytes == 512,
            "projected ranges::sort uses byte count");

    AtLeastBytes functor{48};
    auto equivalent_lambda = [threshold = std::size_t{48}](const Row& row) noexcept {
        return row.bytes >= threshold;
    };
    require(std::ranges::count_if(rows, functor) ==
            std::ranges::count_if(rows, equivalent_lambda),
            "functor and captured lambda express same predicate");

    auto stats = std::make_shared<AllocationStats>();
    {
        std::vector<std::size_t, TrackingAllocator<std::size_t>> tracked{
            TrackingAllocator<std::size_t>{stats}};
        tracked.reserve(5);
        for (const Row& row : live) tracked.push_back(row.bytes);
        require(std::accumulate(tracked.begin(), tracked.end(), std::size_t{0}) == 304,
                "custom allocator does not change vector's value semantics");
        require(stats->allocations > 0 && stats->allocated_bytes >= 5*sizeof(std::size_t),
                "custom allocator observes requests");
    }
    require(stats->allocations == stats->deallocations,
            "typed allocator allocations paired by vector lifetime");

    CountingMemoryResource resource{std::pmr::new_delete_resource()};
    {
        std::pmr::vector<std::size_t> sizes{&resource};
        sizes.reserve(5);
        for (const Row& row : live) sizes.push_back(row.bytes);
        std::pmr::unordered_map<std::pmr::string, std::size_t> index{&resource};
        for (const Row& row : live)
            index.emplace(std::pmr::string{row.name, &resource}, row.bytes);
        require(index.size() == 5 && index.at(std::pmr::string{"sky.tex", &resource}) == 64,
                "pmr unordered_map uses resource for nodes/buckets");
        require(std::accumulate(sizes.begin(), sizes.end(), std::size_t{0}) == 304,
                "pmr vector and custom allocator produce same data result");
        require(resource.allocated_blocks > 0, "pmr resource intercepts allocation");
    }
    require(resource.allocated_blocks == resource.freed_blocks,
            "ordinary upstream resource releases deallocated blocks");

    CountingMemoryResource arena_upstream{std::pmr::new_delete_resource()};
    alignas(std::max_align_t) std::array<std::byte, 128> scratch{};
    {
        std::pmr::monotonic_buffer_resource arena{scratch.data(), scratch.size(),
                                                   &arena_upstream};
        {
            std::pmr::vector<std::uint64_t> pixels{&arena};
            pixels.resize(2048, 7); // exceeds scratch, must ask upstream
            require(pixels.size() == 2048 && pixels[2000] == 7,
                    "monotonic arena supplies live vector storage");
            require(arena_upstream.allocated_blocks > 0,
                    "exhausting stack scratch delegates upstream");
        }
        // pixels' destructor can call deallocate, but monotonic arena does
        // not return its blocks individually; release happens in bulk.
        require(arena_upstream.freed_blocks == 0,
                "monotonic deallocation doesn't return upstream blocks now");
    }
    require(arena_upstream.allocated_blocks == arena_upstream.freed_blocks,
            "arena destruction returns its upstream allocations");

    alignas(std::max_align_t) std::array<std::byte, 64> fixed_scratch{};
    std::pmr::monotonic_buffer_resource bounded{fixed_scratch.data(),
                                                fixed_scratch.size(),
                                                std::pmr::null_memory_resource()};
    bool exhausted = false;
    try {
        std::pmr::vector<std::uint64_t> huge{&bounded};
        huge.resize(2048, 2);
    } catch (const std::bad_alloc&) { exhausted = true; }
    require(exhausted, "fixed arena plus null upstream detects capacity exhaustion");
    std::cout << "asset_ranges_pmr_lab: all checks passed\n";
}
} // namespace allmight::asset_query

int main() {
    try { allmight::asset_query::run(); }
    catch (const std::exception& error) {
        std::cerr << "asset_ranges_pmr_lab failed: " << error.what() << '\n';
        return 1;
    }
}

// TEST HARNESS: never silently discard semantic checks in -DNDEBUG builds.
// This must precede <cassert>; all original assertions remain active under -O2.
#if defined(NDEBUG)
#undef NDEBUG
#endif

// Phase 1 of AllMight: one engine request, two forms of runtime choice.
// Build with C++20, warnings-as-errors, and ASan/UBSan when available.
#include <cassert>
#include <compare>
#include <cmath>
#include <cstdint>
#include <iostream>
#include <limits>
#include <memory>
#include <stdexcept>
#include <string_view>
#include <variant>
#include <type_traits>

// A request is one of three known shapes. std::variant stores the active tag
// and constructs/destructs exactly the active alternative.
struct Clear { float red, green, blue; };
struct DrawMesh { std::uint32_t mesh_id, material_id; };
struct Upload { std::uint64_t byte_count; };
using Request = std::variant<Clear, DrawMesh, Upload>;

struct Counts { int clears=0, draws=0, uploads=0; std::uint64_t bytes=0; };

// An interface means the caller knows what a backend promises, not which
// implementation the application selected at runtime.
class Backend {
public:
    virtual ~Backend() = default; // critical for deleting via Backend*
    virtual void submit(const Request& request) = 0;
    virtual std::string_view name() const noexcept = 0;
};

class CountingBackend final : public Backend {
public:
    CountingBackend(Counts& counts, int& destroyed)
        : counts_(counts), destroyed_(destroyed) {}
    ~CountingBackend() override { ++destroyed_; }

    void submit(const Request& request) override {
        std::visit([this](const auto& operation) {
            using T = std::decay_t<decltype(operation)>;
            if constexpr (std::is_same_v<T, Clear>) {
                ++counts_.clears;
            } else if constexpr (std::is_same_v<T, DrawMesh>) {
                ++counts_.draws;
            } else {
                static_assert(std::is_same_v<T, Upload>);
                ++counts_.uploads;
                counts_.bytes += operation.byte_count;
            }
        }, request);
    }

    std::string_view name() const noexcept override { return "counting"; }
private:
    Counts& counts_; // borrowed: the caller keeps this alive during backend use
    int& destroyed_; // borrowed: test observes the derived destructor
};

class NullBackend final : public Backend {
public:
    void submit(const Request&) override {}
    std::string_view name() const noexcept override { return "null"; }
};

// An asset identity compares by both slot and generation. The compiler can
// synthesize equality and a strong (total) ordering for these integer fields.
struct AssetId {
    std::uint32_t slot;
    std::uint32_t generation;
    auto operator<=>(const AssetId&) const = default;
};

// Nontrivial inherited state can be sliced by copying only its base subobject.
struct NamedObject {
    std::string_view label{"base"};
    virtual ~NamedObject() = default;
    virtual std::string_view kind() const noexcept { return "base"; }
};
struct MeshObject : NamedObject {
    MeshObject() { label = "mesh"; }
    std::string_view kind() const noexcept override { return "mesh"; }
};

// Virtual inheritance creates one shared Root subobject even with two routes.
struct Root { int identifier = 42; };
struct Left : virtual Root {};
struct Right : virtual Root {};
struct Diamond : Left, Right {};

// Default arguments bind using the static type at the call site, whereas
// the selected virtual-function body depends on the dynamic type.
struct DispatchBase {
    virtual ~DispatchBase() = default;
    virtual int reserve(int n = 2) const { return n; }
};
struct DispatchDerived : DispatchBase {
    int reserve(int n = 7) const override { return n * 10; }
};

// Overload resolution selects a viable function before execution. These
// overloads expose the actual static type decision to the test.
constexpr int classify(int) { return 1; }
constexpr int classify(double) { return 2; }

int main() {
    Counts counts;
    int derived_destructor_calls = 0;
    {
        std::unique_ptr<Backend> backend =
            std::make_unique<CountingBackend>(counts, derived_destructor_calls);
        assert(backend->name() == "counting");
        backend->submit(Request{Clear{0.1f, 0.2f, 0.3f}});
        backend->submit(Request{DrawMesh{17u, 4u}});
        backend->submit(Request{Upload{4096u}});
        assert(counts.clears == 1 && counts.draws == 1);
        assert(counts.uploads == 1 && counts.bytes == 4096);

        // dynamic_cast tests dynamic type: null would mean another backend.
        auto* concrete = dynamic_cast<CountingBackend*>(backend.get());
        assert(concrete != nullptr);
        assert(dynamic_cast<NullBackend*>(backend.get()) == nullptr);
    }
    assert(derived_destructor_calls == 1); // virtual deletion reached the derived owner

    Request request = DrawMesh{8u, 2u};
    assert(std::holds_alternative<DrawMesh>(request));
    assert(std::get_if<Upload>(&request) == nullptr);
    request = Upload{128u};
    assert(std::get<Upload>(request).byte_count == 128u);

    const AssetId original{7u, 3u};
    assert((original == AssetId{7u, 3u}));
    assert((original != AssetId{7u, 4u}));
    assert((original <=> AssetId{8u, 1u}) < 0);
    // Floating-point order differs: NaN is *unordered*, not less/equal/greater.
    const double nan = std::numeric_limits<double>::quiet_NaN();
    assert((nan <=> 1.0) == std::partial_ordering::unordered);

    MeshObject mesh;
    NamedObject& borrowed = mesh;
    assert(borrowed.kind() == "mesh"); // virtual call reaches derived override
    NamedObject sliced = mesh;          // makes a *new base object*, losing derived type
    assert(sliced.kind() == "base");

    Diamond diamond;
    Root* via_left = static_cast<Root*>(static_cast<Left*>(&diamond));
    Root* via_right = static_cast<Root*>(static_cast<Right*>(&diamond));
    assert(via_left == via_right && via_left->identifier == 42);

    DispatchDerived derived;
    DispatchBase& base = derived;
    assert(base.reserve() == 20); // base's default 2; derived's body multiplies by 10
    assert(derived.reserve() == 70); // derived's default 7
    assert(classify(3) == 1 && classify(3.0) == 2);

    // A raw union can reuse storage for trivial members, but it provides no
    // automatic active-tag query. Do not read index after writing weight.
    union TrivialCell { std::uint32_t index; float weight; };
    TrivialCell cell{.index=5u};
    assert(cell.index == 5u);
    cell.weight = 0.5f;
    assert(cell.weight == 0.5f);

    std::cout << "backend_choice_lab: all semantic checks passed\n";
}

// Project AllMight, Phase 4 / M014 (Parts 217-230).
// One asset-tile planning problem exposes compile-time evaluation, policy choice,
// static dispatch, and object-layout consequences. This is a CPU-only witness.
#include <array>
#include <cstddef>
#include <cstdint>
#include <functional>
#include <iostream>
#include <limits>
#include <span>
#include <stdexcept>
#include <string_view>
#include <type_traits>
#include <utility>
#include <vector>

namespace allmight {

void require(bool condition, const char* message) {
    if (!condition) throw std::runtime_error(message); // survives -DNDEBUG
}

enum class PixelFormat { R8, RGB8, RGBA8 };

// A type trait represents compile-time information as a type with a value.
// Each specialization defines only the supported format's channel count.
template <PixelFormat Format> struct PixelTraits;
template <> struct PixelTraits<PixelFormat::R8>
    : std::integral_constant<std::size_t, 1> {};
template <> struct PixelTraits<PixelFormat::RGB8>
    : std::integral_constant<std::size_t, 3> {};
template <> struct PixelTraits<PixelFormat::RGBA8>
    : std::integral_constant<std::size_t, 4> {};
static_assert(PixelTraits<PixelFormat::RGB8>::value == 3);
static_assert(std::is_base_of_v<std::integral_constant<std::size_t, 4>,
                                PixelTraits<PixelFormat::RGBA8>>);

struct TileDefinition { std::size_t width, height; };

// Immediate functions require compile-time evaluation for these calls.
// An invalid compile-time configuration must fail during compilation.
consteval TileDefinition make_tile_definition(std::size_t width,
                                               std::size_t height) {
    if (width == 0 || height == 0 || width > 64 || height > 64)
        throw "tile dimensions must be in [1, 64]";
    return {width, height};
}
inline constexpr TileDefinition kDefaultTile = make_tile_definition(8, 8);
static_assert(kDefaultTile.width * kDefaultTile.height == 64);

// A constexpr function can execute during constant evaluation OR at runtime.
// Its preconditions are checked in both cases. No unguarded multiplication.
constexpr std::size_t checked_product(std::size_t x, std::size_t y) {
    if (y != 0 && x > std::numeric_limits<std::size_t>::max() / y)
        throw std::overflow_error("byte-count multiplication overflow");
    return x * y;
}
static_assert(checked_product(8, 4) == 32);

// A 4-bit coordinate is spread into the even bit positions of one byte:
// abcd -> 0a0b0c0d. Two spread coordinates can be interleaved into a
// Morton/Z-order tile code, useful for addressing small 2D tile blocks.
constexpr std::uint8_t spread4(std::uint8_t n) noexcept {
    std::uint8_t result = 0;
    for (unsigned bit = 0; bit != 4; ++bit)
        result |= static_cast<std::uint8_t>(((n >> bit) & 1u) << (2u * bit));
    return result;
}

consteval std::array<std::uint8_t, 16> make_morton_table() {
    std::array<std::uint8_t, 16> result{};
    for (std::size_t n = 0; n < result.size(); ++n)
        result[n] = spread4(static_cast<std::uint8_t>(n));
    return result;
}
inline constexpr auto kSpread4 = make_morton_table();
static_assert(kSpread4[3] == 5 && kSpread4[5] == 17);

constexpr std::uint8_t morton4(std::uint8_t x, std::uint8_t y) {
    if (x >= 16 || y >= 16) throw std::out_of_range("4-bit Morton coordinate");
    return static_cast<std::uint8_t>(kSpread4[x] | (kSpread4[y] << 1));
}
static_assert(morton4(3, 5) == 39);

// constinit promises initialization at static initialization time, not constness
// and not thread safety. This demonstrator is used on a single thread only.
constinit std::uint32_t g_plans_recorded = 0;

// A stateless policy means no application-specific budget, not unchecked math.
// All paths still validate overflow, payload length and format constraints.
struct NoBudgetPolicy {
    void validate(std::size_t) const noexcept {}
};
struct ByteBudgetPolicy {
    std::size_t maximum;
    void validate(std::size_t count) const {
        if (count > maximum) throw std::length_error("tile exceeds byte budget");
    }
};
static_assert(std::is_empty_v<NoBudgetPolicy>);
static_assert(!std::is_empty_v<ByteBudgetPolicy>);

struct TilePlan {
    std::size_t width, height, bytes;
    std::uint8_t example_morton;
    bool alpha;
};

// The CRTP base calls a derived implementation at compile-time-known type.
// It is not a virtual interface and does not provide runtime extensibility.
template <class Derived> struct RecorderBase {
    void record(const TilePlan& plan) {
        static_cast<Derived&>(*this).record_impl(plan);
    }
};
struct CountingRecorder : RecorderBase<CountingRecorder> {
    std::size_t calls = 0, total_bytes = 0;
    void record_impl(const TilePlan& plan) {
        ++calls;
        total_bytes += plan.bytes;
    }
};

// Tags select distinct operations at compile time using ordinary overloads.
struct VerifyPayloadTag {};
struct MetadataOnlyTag {};
void check_payload(std::span<const std::byte> pixels,
                   std::size_t expected, VerifyPayloadTag) {
    if (pixels.size() != expected)
        throw std::invalid_argument("pixel data length does not match plan");
}
void check_payload(std::span<const std::byte>,
                   std::size_t, MetadataOnlyTag) noexcept {
    // This mode produces only a manifest and never asserts buffer readiness.
}

// Template policies are selected at compile time. A no_unique_address member
// allows an empty NoBudgetPolicy to overlap other storage where permitted.
template <PixelFormat Format, class BudgetPolicy, class Recorder>
class TilePlanner {
    [[no_unique_address]] BudgetPolicy budget_;
    Recorder recorder_;
public:
    TilePlanner(BudgetPolicy budget, Recorder recorder)
        : budget_(std::move(budget)), recorder_(std::move(recorder)) {}

    template <class Tag>
    TilePlan prepare(std::size_t width, std::size_t height,
                     std::span<const std::byte> payload, Tag tag) {
        if (width == 0 || height == 0)
            throw std::invalid_argument("tile dimensions cannot be zero");
        const std::size_t pixels = checked_product(width, height);
        const std::size_t bytes =
            checked_product(pixels, PixelTraits<Format>::value);
        budget_.validate(bytes);
        check_payload(payload, bytes, tag);

        // This branch is discarded during instantiation for non-alpha formats.
        // It is an actual compile-time format decision, not a runtime if.
        bool alpha = false;
        if constexpr (Format == PixelFormat::RGBA8) {
            alpha = true;
        }
        TilePlan plan{width, height, bytes, morton4(3, 5), alpha};
        recorder_.record(plan); // static CRTP call into the concrete recorder
        ++g_plans_recorded;
        return plan;
    }

    const Recorder& recorder() const noexcept { return recorder_; }
};

// Classic empty-base optimization (EBO), contrasted with regular and
// C++20 potentially-overlapping members. Sizes are observed, not mandated.
struct PlainPolicyHolder { NoBudgetPolicy policy; std::size_t counter; };
struct EboPolicyHolder : private NoBudgetPolicy { std::size_t counter; };
struct CompactPolicyHolder {
    [[no_unique_address]] NoBudgetPolicy policy;
    std::size_t counter;
};

void run() {
    require(kDefaultTile.width == 8, "consteval configuration");
    require(morton4(3, 5) == 39, "Morton table and composition");
    require(checked_product(7, 6) == 42, "constexpr function at runtime");
    const std::size_t value = 13;
    require(checked_product(value, 3) == 39, "runtime constexpr call");

    using RgbaPlanner = TilePlanner<PixelFormat::RGBA8,
                                    ByteBudgetPolicy, CountingRecorder>;
    RgbaPlanner limited{ByteBudgetPolicy{64}, CountingRecorder{}};
    std::vector<std::byte> rgba(8 * 2 * 4, std::byte{0x7f});
    TilePlan accepted = limited.prepare(8, 2, rgba, VerifyPayloadTag{});
    require(accepted.bytes == 64 && accepted.alpha,
            "RGBA tile validated and recorded");
    require(limited.recorder().calls == 1 &&
            limited.recorder().total_bytes == 64, "static CRTP recorder");

    bool too_large = false;
    try {
        (void)limited.prepare(8, 3, {}, MetadataOnlyTag{}); // 96 > 64
    } catch (const std::length_error&) { too_large = true; }
    require(too_large && limited.recorder().calls == 1,
            "budget failure must not publish a plan");

    bool wrong_payload = false;
    try {
        (void)limited.prepare(4, 4, {}, VerifyPayloadTag{}); // 64 required
    } catch (const std::invalid_argument&) { wrong_payload = true; }
    require(wrong_payload && limited.recorder().calls == 1,
            "payload failure leaves recorder unchanged");

    TilePlanner<PixelFormat::RGB8, NoBudgetPolicy, CountingRecorder>
        manifest{NoBudgetPolicy{}, CountingRecorder{}};
    auto metadata = manifest.prepare(4, 4, {}, MetadataOnlyTag{});
    require(metadata.bytes == 48 && !metadata.alpha,
            "manifest is a plan only, not a verified upload");
    require(manifest.recorder().calls == 1,
            "second static policy and recorder instance");

    bool overflow = false;
    try {
        (void)manifest.prepare(std::numeric_limits<std::size_t>::max(),
                               2, {}, MetadataOnlyTag{});
    } catch (const std::overflow_error&) { overflow = true; }
    require(overflow && manifest.recorder().calls == 1,
            "overflow checked before byte multiplication");

    // Runtime type erasure has a different tradeoff from the statically
    // selected CRTP Recorder. It can hold a runtime-selected callable target.
    std::size_t observed = 0;
    std::function<void(const TilePlan&)> erased =
        [&observed](const TilePlan& plan) { observed += plan.bytes; };
    erased(metadata);
    require(observed == 48, "type-erased runtime callable");
    erased = {}; // release its captured target

    require(g_plans_recorded == 2, "constinit counter updated by accepted plans");
    require(sizeof(PlainPolicyHolder) >= sizeof(std::size_t),
            "ordinary member layout observed");
    require(sizeof(EboPolicyHolder) >= sizeof(std::size_t),
            "EBO layout observed");
    require(sizeof(CompactPolicyHolder) >= sizeof(std::size_t),
            "no_unique_address layout observed");
    std::cout << "Layout bytes (plain/EBO/member): "
              << sizeof(PlainPolicyHolder) << '/' << sizeof(EboPolicyHolder)
              << '/' << sizeof(CompactPolicyHolder) << '\n';
    std::cout << "compile_time_asset_policy_lab: all checks passed\n";
}
} // namespace allmight

int main() {
    try { allmight::run(); }
    catch (const std::exception& e) {
        std::cerr << "compile_time_asset_policy_lab failed: " << e.what() << '\n';
        return 1;
    }
}

// Standalone C++20 contact cache policy witness; no dependency on Kairo runtime.
// Build: c++ -std=c++20 -O2 -Wall -Wextra -Wpedantic -Werror contact_cache_lab.cpp -o /tmp/contact_cache && /tmp/contact_cache
#include <algorithm>
#include <cmath>
#include <cstdint>
#include <iostream>
#include <limits>
#include <map>
#include <stdexcept>
#include <vector>

struct Vec2 { double x{}, y{}; };
constexpr Vec2 operator*(Vec2 a, double s) { return {a.x*s, a.y*s}; }
constexpr double dot(Vec2 a, Vec2 b) { return a.x*b.x+a.y*b.y; }
constexpr Vec2 tangent(Vec2 n) { return {-n.y, n.x}; }
void require(bool b, const char* msg) { if (!b) throw std::runtime_error(msg); }
void near(double a, double b, double eps=1e-10) {
    require(std::isfinite(a) && std::isfinite(b) && std::abs(a-b)<=eps, "unexpected numeric result");
}
Vec2 unit(Vec2 n) {
    require(std::isfinite(n.x) && std::isfinite(n.y), "nonfinite normal");
    const double length=std::hypot(n.x,n.y);
    require(length>1e-12 && std::isfinite(length), "degenerate normal");
    return n*(1.0/length);
}
// Feature indices come from a *narrowphase* feature matcher. They are not array indices.
// Pair orientation is canonical; swapping bodies is not interchangeable with reusing this cache.
struct Key {
    std::uint64_t bodyA{},bodyB{},featureA{},featureB{};
    auto operator<=>(const Key&) const = default;
};
struct ContactInput {
    Key key{};
    Vec2 normal{0,1};
    double friction{}, timeStep{};
};
struct CachedImpulse {
    Vec2 normal{0,1};
    double normalMagnitude{}, tangentMagnitude{}, friction{},timeStep{};
    std::uint64_t lastSeenFrame{};
};
struct Seed { double normal{}, tangent{}; bool reused{}; };
class ContactCache {
    std::map<Key,CachedImpulse> entries_;
    std::uint64_t frame_{};
    static constexpr double minimumNormalCosine=0.9659258262890683; // 15 deg
    static constexpr double maxStepRatio=2.0;
    static void validate(const ContactInput& in) {
        require(in.key.bodyA<in.key.bodyB, "body pair must have canonical orientation");
        require(std::isfinite(in.friction) && in.friction>=0, "invalid friction");
        require(std::isfinite(in.timeStep) && in.timeStep>0, "invalid timestep");
        (void)unit(in.normal);
    }
public:
    void begin_frame(std::uint64_t id) {
        require(id>frame_, "frame ids must increase"); frame_=id;
    }
    Seed lookup(const ContactInput& in) const {
        require(frame_>0, "begin_frame required"); validate(in);
        const auto it=entries_.find(in.key);
        if(it==entries_.end()) return {};
        const auto& old=it->second;
        // Only the immediately previous frame may warm start. Missing a frame invalidates state.
        if(old.lastSeenFrame!=frame_-1) return {};
        const Vec2 previous=unit(old.normal),current=unit(in.normal);
        const double alignment=dot(previous,current);
        if(alignment<minimumNormalCosine) return {};
        const double ratio=in.timeStep/old.timeStep;
        if(!std::isfinite(ratio) || ratio<1/maxStepRatio || ratio>maxStepRatio) return {};
        // A material edit invalidates the tangential cache, not the physical normal reaction.
        // Project the previous world-space tangential impulse onto the current tangent.
        const Vec2 previousTangentImpulse=tangent(previous)*old.tangentMagnitude;
        const double normal=old.normalMagnitude*ratio;
        const double tangentValue=(old.friction==in.friction)
            ? dot(previousTangentImpulse,tangent(current))*ratio : 0;
        return {normal,std::clamp(tangentValue,-in.friction*normal,in.friction*normal),true};
    }
    void store(const ContactInput& in,double normalImpulse,double tangentImpulse) {
        require(frame_>0,"begin_frame required"); validate(in);
        require(std::isfinite(normalImpulse) && normalImpulse>=0,"invalid normal impulse");
        require(std::isfinite(tangentImpulse),"invalid tangent impulse");
        require(std::abs(tangentImpulse)<=in.friction*normalImpulse+1e-9,"friction cone exceeded");
        // A repeated write for the same feature in one frame indicates a duplicate manifold row.
        const auto it=entries_.find(in.key);
        require(it==entries_.end() || it->second.lastSeenFrame!=frame_,"duplicate feature key");
        entries_[in.key]={unit(in.normal),normalImpulse,tangentImpulse,in.friction,in.timeStep,frame_};
    }
    void prune() {
        for(auto it=entries_.begin();it!=entries_.end();) {
            if(it->second.lastSeenFrame!=frame_)it=entries_.erase(it); else ++it;
        }
    }
    std::size_t size() const { return entries_.size(); }
};
int main() {
    const Key id{4,9,2,7};
    ContactCache cache; ContactInput in{id,{0,1},0.5,1.0/60.0};
    cache.begin_frame(1);
    require(!cache.lookup(in).reused,"new feature had cache");
    cache.store(in,2,0.5);
    cache.begin_frame(2);
    auto seed=cache.lookup(in);
    require(seed.reused,"persistent identity not reused"); near(seed.normal,2);near(seed.tangent,0.5);
    // Rotating the tangent frame changes the scalar, but preserves the projection.
    const double a=10*3.14159265358979323846/180;
    ContactInput rotated=in;rotated.normal={-std::sin(a),std::cos(a)};
    seed=cache.lookup(rotated);require(seed.reused,"small normal drift invalidated");
    near(seed.tangent,0.5*std::cos(a));
    ContactInput sharp=in;sharp.normal={-0.5,std::sqrt(0.75)};
    require(!cache.lookup(sharp).reused,"large normal drift accepted");
    ContactInput swapped=in;swapped.key={9,4,7,2};
    bool rejected=false;try{(void)cache.lookup(swapped);}catch(const std::runtime_error&){rejected=true;}
    require(rejected,"reversed body order accepted");
    ContactInput changedFeature=in;changedFeature.key.featureB=8;
    require(!cache.lookup(changedFeature).reused,"different geometry feature reused");
    ContactInput halfStep=in;halfStep.timeStep*=0.5;
    seed=cache.lookup(halfStep);require(seed.reused,"bounded timestep change rejected");
    near(seed.normal,1);near(seed.tangent,0.25);
    ContactInput jumpStep=in;jumpStep.timeStep*=4;
    require(!cache.lookup(jumpStep).reused,"large timestep jump accepted");
    ContactInput changedFriction=in;changedFriction.friction=0.1;
    seed=cache.lookup(changedFriction);require(seed.reused,"material edit erased normal cache");
    near(seed.normal,2);near(seed.tangent,0);
    cache.store(in,1,0.25);
    rejected=false;try{cache.store(in,1,0.25);}catch(const std::runtime_error&){rejected=true;}
    require(rejected,"duplicate feature admitted");
    cache.prune();require(cache.size()==1,"prune failure");
    cache.begin_frame(4);require(!cache.lookup(in).reused,"skipped frame reused");
    cache.prune();require(cache.size()==0,"stale feature survived prune");
    ContactInput bad=in;bad.normal={0,0};
    rejected=false;try{(void)cache.lookup(bad);}catch(const std::runtime_error&){rejected=true;}
    require(rejected,"degenerate normal accepted");
    std::cout<<"contact cache: identity, tangent transport, timestep, invalidation PASS\n";
