        near(ds[0].velocity.x,-1,1e-7);near(ds[1].velocity.x,0,1e-7);
        near(ds[2].velocity.x,1,1e-7);
        near(momentum(ds).x,before.x);near(energy(ds),k,1e-7);
    }
    {
        std::vector<Disk> ds{{1,{0,0},{1,0},1,1},{2,{10,0},{2,0},1,1}};
        const auto r=simulate(ds,2);
        check(r.events==0,"separating contacts should not collide");
        near(ds[0].centre.x,2);near(ds[1].centre.x,14);
    }
    {
        // No implicit correction of pre-existing deep overlap.
        std::vector<Disk> ds{{1,{0,0},{0,0},1,1},{2,{1,0},{0,0},1,1}};
        bool rejected=false;
        try{(void)simulate(ds,0.5);}catch(const std::runtime_error&){rejected=true;}
        check(rejected,"initial overlap was not rejected");
    }
    {
        std::vector<Disk> ds{{1,{-4,0},{2,0},1,1},{2,{4,0},{-2,0},1,1}};
        bool rejected=false;
        try{(void)simulate(ds,2,1,0);}catch(const std::runtime_error&){rejected=true;}
        check(rejected,"event budget failure was silent");
    }
    {
        // The first impact starts a second event later in the same frame.
        std::vector<Disk> ds{{1,{-6,0},{4,0},1,1},{2,{0,0},{0,0},1,1},
                             {3,{6,0},{0,0},1,1}};
        const auto r=simulate(ds,3,1);
        check(r.events==2&&r.batches==2,"sequential event rescheduling failed");
        near(ds[0].velocity.x,0);near(ds[1].velocity.x,0);
        near(ds[2].velocity.x,4);near(momentum(ds).x,4);
    }
    {
        // Perfectly inelastic velocity-level impact preserves momentum but loses energy.
        std::vector<Disk> ds{{1,{-3,0},{2,0},1,1},{2,{3,0},{0,0},1,1}};
        const auto originalMomentum=momentum(ds).x;
        const auto initialEnergy=energy(ds);
        const auto r=simulate(ds,2,0);
        check(r.events==1,"inelastic impact not detected");
        near(ds[0].velocity.x,1);near(ds[1].velocity.x,1);
        near(momentum(ds).x,originalMomentum);
        check(energy(ds)<initialEnergy,"inelastic impact gained energy");
    }
    {
        // Stable IDs must not alias; zero-duration steps must not mutate velocities.
        std::vector<Disk> ds{{1,{0,0},{1,0},1,1},{2,{10,0},{0,0},1,1}};
        const auto r=simulate(ds,0);
        check(r.events==0,"zero duration generated event");
        near(ds[0].centre.x,0);
        ds[1].id=1;
        bool rejected=false;
        try{(void)simulate(ds,1);}catch(const std::runtime_error&){rejected=true;}
        check(rejected,"duplicate stable identities accepted");
    }
    std::cout << "disk event pipeline: 9 scene suites PASS\n";
}
#endif // ALLMIGHT_EVENT_PIPELINE_NO_MAIN

// Seeded property regression for the independently implemented disk event solver.
// This is a controlled isolated-pair experiment, not a general solver proof.
// Build: c++ -std=c++20 -O2 -Wall -Wextra -Wpedantic -Werror tools/labs/disk_event_property_lab.cpp -o /tmp/disk_property && /tmp/disk_property
#define ALLMIGHT_EVENT_PIPELINE_NO_MAIN
#include "disk_event_pipeline_lab.cpp"
#undef ALLMIGHT_EVENT_PIPELINE_NO_MAIN
#include <random>

int main() {
    // Fixed seed makes every failing case reproducible on the same toolchain.
    std::mt19937_64 rng(0xA11A11u);
    std::uniform_real_distribution<double> initialSeparation(3.0,15.0);
    std::uniform_real_distribution<double> closingSpeed(0.2,15.0);
    std::uniform_real_distribution<double> mass(0.2,8.0);
    std::uniform_real_distribution<double> restitution(0.0,1.0);
    constexpr int trialCount=10000;
    for(int trial=0;trial<trialCount;++trial) {
        const double separation=initialSeparation(rng);
        const double speed=closingSpeed(rng);
        const double massA=mass(rng),massB=mass(rng);
        const double e=restitution(rng);
        // The first disk approaches the second on the x axis.
        std::vector<Disk> disks{
            {1,{0,0},{speed,0},1,1/massA},
            {2,{separation,0},{0,0},1,1/massB}
        };
        const double duration=(separation-2)/speed+0.1;
        const Vec2 initialMomentum=momentum(disks);
        const double initialEnergy=energy(disks);
        Result result{};
        try {
            result=simulate(disks,duration,e);
        } catch(const std::exception& ex) {
            std::cerr<<"trial "<<trial<<" separation "<<separation
                     <<" speed "<<speed<<" massA "<<massA
                     <<" massB "<<massB<<" restitution "<<e
                     <<" exception "<<ex.what()<<'\n';
            throw;
        }
        check(result.events==1,"expected one isolated collision");
        const double outgoingSpeed=disks[1].velocity.x-disks[0].velocity.x;
        // Newton restitution: outgoing separation speed equals e times incoming closing speed.
        check(std::abs(outgoingSpeed-e*speed)<=1e-8*std::max(1.0,speed),
              "restitution property failed");
        const double finalMomentum=momentum(disks).x;
        check(std::abs(finalMomentum-initialMomentum.x)<=
              1e-8*std::max(1.0,std::abs(initialMomentum.x)),
              "linear momentum property failed");
        check(energy(disks)<=initialEnergy+1e-8*std::max(1.0,initialEnergy),
              "energy unexpectedly increased");
    }
    std::cout<<"disk event properties: 10000 seeded isolated collisions PASS\n";
}

#!/usr/bin/env python3
"""Compile exact book excerpts; prove ordinary behavior AND its throwing-move gap."""
import argparse
from pathlib import Path
import shutil
import subprocess
import sys
import tempfile

# Parse the actual Markdown blocks, rather than copying a different ECS model.
sys.path.insert(0, str(Path(__file__).resolve().parents[1]))
from note_integrity import code_blocks

ROOT = Path(__file__).resolve().parents[2]
BOOK = ROOT / 'Continuous Notes/Game Engine - From First Frame to Living Worlds.md'

DRIVER = r"""
#include <iostream>
struct ThrowingComponent {
    int value;
    inline static bool fail = false;
    explicit ThrowingComponent(int v) : value(v) {}
    ThrowingComponent(const ThrowingComponent&) = default;
    ThrowingComponent(ThrowingComponent&&) noexcept = default;
    ThrowingComponent& operator=(ThrowingComponent&& other) {
        // Throw before touching the value, so any broken entity metadata is
        // attributable to Remove's ordering, not a partially assigned T.
        if (fail) throw std::runtime_error("deliberate component move failure");
        value = other.value;
        return *this;
    }
};

int main() {
    SparseSet<int> pool;
    const Entity old{0, 1}, second{1, 1}, replacement{0, 2};
    pool.Emplace(old, 7);
    pool.Emplace(second, 9);
    if (pool.Get(old) != 7 || pool.Get(second) != 9) return 1;
    if (!pool.Remove(old)) return 2;
    // Swap-removal must repair the surviving entity's reverse map.
    if (pool.Contains(old) || pool.Get(second) != 9 || pool.Size() != 1) return 3;
    pool.Emplace(replacement, 11);
    if (pool.Contains(old) || pool.Get(replacement) != 11) return 4;

    SparseSet<ThrowingComponent> unsafe;
    unsafe.Emplace(old, 10);
    unsafe.Emplace(second, 20);
    ThrowingComponent::fail = true;
    bool caught = false;
    try { unsafe.Remove(old); }
    catch (const std::runtime_error&) { caught = true; }
    ThrowingComponent::fail = false;
    // This EXPECTED counterexample is evidence of an unsupported T contract.
    // Passing this check does not make the current generic Remove safe.
    if (!caught || unsafe.Entities().size() != 2 ||
        unsafe.Entities()[0] != second || unsafe.Entities()[1] != second) return 5;
    if (unsafe.Contains(old)) return 6;
    std::cout << "PASS: normal swap-remove and generation reuse; "
                 "EXPECTED throwing-move invariant failure reproduced\n";
}
"""


def assemble(book):
    blocks = [b.body for b in code_blocks(book.read_text()) if b.language == 'cpp']
    # Matching exact declarations keeps introductory sketches out of this check.
    entities = [b for b in blocks if 'struct Entity final' in b and '#include <cstdint>' in b]
    pools = [b for b in blocks if 'class SparseSet' in b and
             'std::is_nothrow_move_assignable_v<T>' in b and 'EnsureSparse' in b]
    if len(entities) != 1 or len(pools) != 1:
        raise ValueError('Expected one exact Entity and full SparseSet excerpt')
    # The book fragment omits a direct header; add it explicitly for this TU.
    return '#include <type_traits>\n' + entities[0] + '\n' + pools[0] + '\n' + DRIVER


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument('book', nargs='?', type=Path, default=BOOK)
    parser.add_argument('--compiler', default='c++')
    args = parser.parse_args()
    compiler = shutil.which(args.compiler)
    if not compiler:
        parser.error('A C++20 compiler is required')
    with tempfile.TemporaryDirectory(prefix='allmight-ecs-excerpt-') as folder:
        source = Path(folder) / 'ecs.cpp'
        binary = Path(folder) / 'ecs'
        source.write_text(assemble(args.book))
        command = [compiler, '-std=c++20', '-O2', '-DNDEBUG', '-Wall',
                   '-Wextra', '-Wpedantic', '-Werror', str(source), '-o', str(binary)]
        subprocess.run(command, check=True)
        subprocess.run([str(binary)], check=True)


if __name__ == '__main__':
    main()

// Executable witnesses for four first-use teaching bridges.
// Build: c++ -std=c++20 -O2 -Wall -Wextra -Wpedantic -Werror
//        tools/labs/first_use_contract_lab.cpp -o /tmp/first_use && /tmp/first_use
#include <array>
#include <algorithm>
#include <stdexcept>
#include <cmath>
#include <cstdint>
#include <limits>
#include <optional>
#include <utility>

// Keep validation enabled when NDEBUG removes ordinary assert() checks.
void require(bool condition) {
    if (!condition) throw std::runtime_error("first-use contract violated");
}

struct Vec2 { double x, y; };
struct Coordinates { double first, second, residual; };

// Solve [b1 b2] * c = world without constructing the inverse matrix.
// This is a teaching-sized 2x2 pivoted elimination, not a general LAPACK replacement.
std::optional<Coordinates> recover_coordinates(Vec2 b1, Vec2 b2, Vec2 world) {
    if (!std::isfinite(b1.x) || !std::isfinite(b1.y) ||
        !std::isfinite(b2.x) || !std::isfinite(b2.y) ||
        !std::isfinite(world.x) || !std::isfinite(world.y)) return std::nullopt;
    double a[2][3] = {{b1.x, b2.x, world.x}, {b1.y, b2.y, world.y}};
    const double scale = std::max({std::abs(b1.x), std::abs(b1.y),
                                   std::abs(b2.x), std::abs(b2.y)});
    if (scale == 0 || !std::isfinite(scale)) return std::nullopt;
    // The threshold is relative to the input matrix, not a fixed world-space distance.
    const double threshold = 32 * std::numeric_limits<double>::epsilon() * scale;
    for (int col = 0; col != 2; ++col) {
        int pivot = (std::abs(a[1][col]) > std::abs(a[col][col])) ? 1 : col;
        // Only row 1 can replace row 0 on the first pivot. At col 1, pivot stays 1.
        if (col == 1) pivot = 1;
        if (!(std::abs(a[pivot][col]) > threshold)) return std::nullopt;
        if (pivot != col) for (int j = 0; j != 3; ++j) std::swap(a[col][j], a[pivot][j]);
        if (col == 0) {
            const double m = a[1][0] / a[0][0];
            a[1][1] -= m * a[0][1];
            a[1][2] -= m * a[0][2];
            a[1][0] = 0;
        }
    }
    const double second = a[1][2] / a[1][1];
    const double first = (a[0][2] - a[0][1] * second) / a[0][0];
    const double dx = b1.x * first + b2.x * second - world.x;
    const double dy = b1.y * first + b2.y * second - world.y;
    if (!std::isfinite(first) || !std::isfinite(second) ||
        !std::isfinite(dx) || !std::isfinite(dy)) return std::nullopt;
    return Coordinates{first, second, std::hypot(dx, dy)};
}

struct Item { std::uint32_t key; std::uint32_t identity; };

// Stable two-bit radix sort. Only pointers are swapped: no in-place scatter.
template <std::size_t N>
std::array<Item, N> stable_two_bit_radix(std::array<Item, N> initial) {
    std::array<Item, N> scratch{};
    auto* read = &initial;
    auto* write = &scratch;
    for (unsigned bit = 0; bit != 2; ++bit) {
        std::size_t zeros = 0;
        for (const Item& item : *read) zeros += ((item.key >> bit) & 1u) == 0u;
        std::size_t next_zero = 0, next_one = zeros;
        for (const Item& item : *read) {
            // Each item has one disjoint destination. Relative order within a bin survives.
            const bool one = ((item.key >> bit) & 1u) != 0u;
            (*write)[one ? next_one++ : next_zero++] = item;
        }
        std::swap(read, write);
    }
    return *read; // This also works for an odd number of passes if the loop changes.
}

struct Splat { double q, opacity; std::array<double, 3> color; };
struct Composite { std::array<double, 3> color; double transmittance; };

// Input splats must already be sorted front-to-back in one declared depth convention.
// Color is linear and premultiplied into the accumulated result by alpha at each step.
std::optional<Composite> composite_splats(const Splat* splats, std::size_t count) {
    Composite out{{0, 0, 0}, 1};
    for (std::size_t i = 0; i < count; ++i) {
        const Splat& s = splats[i];
        if (!std::isfinite(s.q) || s.q < 0 || !std::isfinite(s.opacity) ||
            s.opacity < 0 || s.opacity > 1) return std::nullopt;
        for (double component : s.color)
            if (!std::isfinite(component) || component < 0 || component > 1)
                return std::nullopt;
        if (s.q > 9) continue; // Deliberate truncated footprint, not zero Gaussian support.
        const double alpha = std::clamp(s.opacity * std::exp(-0.5 * s.q), 0.0, 0.999);
        for (int ch = 0; ch != 3; ++ch)
            out.color[ch] += out.transmittance * alpha * s.color[ch];
        out.transmittance *= (1.0 - alpha);
        if (out.transmittance < 1e-4) break; // Bounded omitted color under [0,1] assumption.
    }
    return out; // Background, if any, adds T * background in the same linear space.
}

// A deterministic quadrature of the expectation of a two-technique MIS estimator.
// Both PDFs have full support in the open interval (0,1); f(x) = x^2.
double expected_mis_integral() {
    constexpr int slices = 10000;
    double total = 0;
    for (int i = 0; i < slices; ++i) {
        const double x = (i + 0.5) / slices;
        const double pa = 2 * x, pb = 2 * (1 - x);
        const double wa = (pa * pa) / (pa * pa + pb * pb);
        const double wb = 1 - wa;
        const double f = x * x;
        // p_a * (w_a f / p_a) + p_b * (w_b f / p_b): the two expectations.
        total += (pa * (wa * f / pa) + pb * (wb * f / pb)) / slices;
    }
    return total;
}

int main() {
    const auto c = recover_coordinates({1, 0}, {1, 1}, {3, 2});
    require(c && std::abs(c->first - 1) < 1e-12 &&
           std::abs(c->second - 2) < 1e-12 && c->residual < 1e-12);
    require(!recover_coordinates({1, 0}, {1, 0}, {3, 2}));

    auto sorted = stable_two_bit_radix<5>({{{3, 0}, {1, 1}, {2, 2}, {0, 3}, {2, 4}}});
    const std::array<std::uint32_t, 5> expected_keys{0, 1, 2, 2, 3};
    for (std::size_t i = 0; i < sorted.size(); ++i) require(sorted[i].key == expected_keys[i]);
    require(sorted[2].identity == 2 && sorted[3].identity == 4); // Stability.

    const std::array<Splat, 2> front_to_back{{{0, 0.6, {1, 0, 0}},
                                              {0, 0.5, {0, 0, 1}}}};
    const auto composed = composite_splats(front_to_back.data(), front_to_back.size());
    require(composed && std::abs(composed->color[0] - 0.6) < 1e-12 &&
           std::abs(composed->color[2] - 0.2) < 1e-12 &&
           std::abs(composed->transmittance - 0.2) < 1e-12);
    require(std::abs(expected_mis_integral() - 1.0 / 3.0) < 1e-8);
}

// AllMight M013 / Parts 201-216: generic, constrained asset preparation.
// C++20. This is a CPU-side laboratory; it does not use Vulkan or Metal.
#include <array>
#include <cstddef>
#include <cstdint>
#include <iostream>
#include <limits>
#include <optional>
#include <stdexcept>
#include <string_view>
#include <type_traits>
#include <utility>
#include <vector>
#include <concepts>

namespace allmight {

void require(bool condition, const char* message) {
    if (!condition) throw std::runtime_error(message); // also works with NDEBUG
}

// A mesh stores indices. Two constructors record whether the incoming vector
// was borrowed and copied or was an rvalue whose storage could be transferred.
struct Mesh {
    std::vector<std::uint32_t> indices;
    bool copied_input;
    explicit Mesh(const std::vector<std::uint32_t>& input)
        : indices(input), copied_input(true) {}
    explicit Mesh(std::vector<std::uint32_t>&& input)
        : indices(std::move(input)), copied_input(false) {}
};

// The non-type template parameter is part of the actual texture type.
// Channel count is validated at compile time, while texel_count is checked
// at runtime because it comes from decoded input.
template <std::size_t Channels>
struct Texture {
    static_assert(Channels >= 1 && Channels <= 4, "supported channel counts: 1..4");
    std::array<std::uint8_t, Channels> first_texel{};
    std::size_t texel_count{};
};

// A declared, undefined primary trait does NOT claim every C++ type is an
// asset. An explicit specialization enables Mesh; a partial specialization
// enables every supported Texture<Channels> family member.
template <class T>
struct AssetTraits;

template <>
struct AssetTraits<Mesh> {
    static constexpr std::string_view label = "mesh";
    static std::size_t byte_size(const Mesh& mesh) {
        constexpr std::size_t element_size = sizeof(std::uint32_t);
        if (mesh.indices.size() > std::numeric_limits<std::size_t>::max() / element_size)
            throw std::overflow_error("mesh size overflow");
        return mesh.indices.size() * element_size;
    }
};

template <std::size_t Channels>
struct AssetTraits<Texture<Channels>> {
    static constexpr std::string_view label = "texture";
    static std::size_t byte_size(const Texture<Channels>& texture) {
        if (texture.texel_count > std::numeric_limits<std::size_t>::max() / Channels)
            throw std::overflow_error("texture size overflow");
        return texture.texel_count * Channels;
    }
};

// A requires-expression tests well-formedness and result types. It does not
// run byte_size(), so data-dependent overflow still needs runtime checking.
template <class T>
concept Uploadable = requires(const T& asset) {
    { AssetTraits<T>::label } -> std::convertible_to<std::string_view>;
    { AssetTraits<T>::byte_size(asset) } -> std::same_as<std::size_t>;
};

struct UnknownAsset {};
static_assert(Uploadable<Mesh>);
static_assert(Uploadable<Texture<3>>);
static_assert(Uploadable<Texture<4>>);
static_assert(!Uploadable<UnknownAsset>);

// This is the earlier SFINAE idiom: when substitution of an expression fails,
// specialization is removed instead of producing a hard error in this context.
template <class T, class = void>
struct HasByteSize : std::false_type {};

template <class T>
struct HasByteSize<T, std::void_t<decltype(AssetTraits<T>::byte_size(
                                       std::declval<const T&>()))>> : std::true_type {};

static_assert(HasByteSize<Mesh>::value);
static_assert(HasByteSize<Texture<4>>::value);
static_assert(!HasByteSize<UnknownAsset>::value);

// Two viable function templates have otherwise equivalent parameter patterns.
// For Uploadable types, the constrained overload is the more specialized one.
template <class T>
constexpr std::string_view route(const T&) { return "unsupported"; }

template <Uploadable T>
constexpr std::string_view route(const T&) { return AssetTraits<T>::label; }

// A function template deduces T from the argument. No caller must write <Mesh>.
template <Uploadable T>
std::size_t asset_bytes(const T& asset) {
    return AssetTraits<T>::byte_size(asset);
}

// A comma fold evaluates each append from left to right. The empty pack is
// accepted and returns zero. All additions are checked for overflow.
template <Uploadable... T>
std::size_t total_bytes(const T&... assets) {
    std::size_t result = 0;
    [[maybe_unused]] const auto add_checked = [&result](std::size_t next) {
        if (next > std::numeric_limits<std::size_t>::max() - result)
            throw std::overflow_error("batch size overflow");
        result += next;
    };
    (add_checked(asset_bytes(assets)), ...);
    return result;
}

struct AssetId { std::size_t slot; };

// Class template: T specifies the stored semantic type; Capacity is a
// non-type template argument. A fixed array makes stable slots explicit.
// This is not a network format or a GPU resource descriptor.
template <Uploadable T, std::size_t Capacity>
class AssetDepot {
    static_assert(Capacity > 0, "at least one asset slot is required");
    std::array<std::optional<T>, Capacity> slots_{};
    std::size_t count_ = 0;
public:
    std::size_t size() const noexcept { return count_; }
    static constexpr std::size_t capacity() noexcept { return Capacity; }

    // Args&& are forwarding references because Args are deduced here.
    // std::forward<Args> preserves the original argument categories.
    // Construct into the next *unpublished* optional; increment count only
    // after construction succeeds. Existing assets stay untouched on throw.
    template <class... Args>
        requires std::constructible_from<T, Args&&...>
    AssetId emplace(Args&&... args) {
        if (count_ == Capacity) throw std::length_error("asset depot full");
        slots_[count_].emplace(std::forward<Args>(args)...);
        return AssetId{count_++};
    }

    const T& get(AssetId id) const {
        if (id.slot >= count_) throw std::out_of_range("invalid asset slot");
        return *slots_[id.slot]; // only slots below count_ are engaged
    }
};

// The language's reference-collapsing rules make T deduce as U& for an
// lvalue, and U for an rvalue; T&& then collapses respectively to U& or U&&.
template <class T>
constexpr bool was_lvalue(T&&) { return std::is_lvalue_reference_v<T>; }

// A failed constrained call can be queried instead of being compiled as an
// intentionally broken expression. This also verifies the actual API surface.
template <class Store, class... Args>
concept CanEmplace = requires(Store& store, Args&&... args) {
    { store.emplace(std::forward<Args>(args)...) } -> std::same_as<AssetId>;
};

using MeshDepot = AssetDepot<Mesh, 2>;
static_assert(CanEmplace<MeshDepot, std::vector<std::uint32_t>&>);
static_assert(CanEmplace<MeshDepot, std::vector<std::uint32_t>>);
static_assert(!CanEmplace<MeshDepot, int>);

// A throwing asset makes the unpublished-slot invariant observable.
struct CheckedShader {
    int version;
    explicit CheckedShader(int v) : version(v) {
        if (v <= 0) throw std::invalid_argument("shader version must be positive");
    }
};

template <>
struct AssetTraits<CheckedShader> {
    static constexpr std::string_view label = "shader";
    static std::size_t byte_size(const CheckedShader&) { return sizeof(int); }
};

void run() {
    MeshDepot meshes;
    std::vector<std::uint32_t> input{3, 7, 9};
    require(was_lvalue(input), "lvalue category should be preserved");
    require(!was_lvalue(std::vector<std::uint32_t>{}), "temporary is an rvalue");

    // An lvalue chooses the const& constructor, making a semantic copy.
    const AssetId copied = meshes.emplace(input);
    require(meshes.get(copied).copied_input, "lvalue copied, not moved");
    require(input.size() == 3, "copy leaves the original usable");

    // An rvalue chooses the && constructor, making the source transferable.
    const AssetId moved = meshes.emplace(std::move(input));
    require(!meshes.get(moved).copied_input, "rvalue selects move path");
    require(meshes.get(moved).indices.size() == 3, "moved payload is retained");
    // Do not assume a moved-from vector has a particular size.

    bool full_rejected = false;
    try { meshes.emplace(std::vector<std::uint32_t>{11}); }
    catch (const std::length_error&) { full_rejected = true; }
    require(full_rejected && meshes.size() == 2, "full store preserves prior assets");

    AssetDepot<CheckedShader, 2> shaders;
    const AssetId good = shaders.emplace(3);
    bool bad_rejected = false;
    try { shaders.emplace(-1); }
    catch (const std::invalid_argument&) { bad_rejected = true; }
    require(bad_rejected && shaders.size() == 1, "throwing construction stays unpublished");
    require(shaders.get(good).version == 3, "prior shader is intact");
    const AssetId second = shaders.emplace(4);
    require(second.slot == 1 && shaders.size() == 2, "failed slot can be reused");

    Texture<4> rgba{{255, 0, 128, 255}, 12};
    Texture<3> rgb{{12, 23, 34}, 5};
    require(asset_bytes(meshes.get(copied)) == 3 * sizeof(std::uint32_t),
            "mesh trait counts stored indices");
    require(asset_bytes(rgba) == 48 && asset_bytes(rgb) == 15,
            "texture partial specialization accounts for channels");
    require(total_bytes(meshes.get(copied), rgba, rgb) == 75,
            "heterogeneous checked comma fold sums bytes");
    require(total_bytes() == 0, "empty fold produces zero");
    require(route(rgba) == "texture", "constrained overload wins for Texture");
    require(route(meshes.get(copied)) == "mesh", "constrained overload wins for Mesh");
    require(route(UnknownAsset{}) == "unsupported", "fallback is deliberate");

    bool overflow_rejected = false;
    Texture<4> enormous{{0, 0, 0, 0}, std::numeric_limits<std::size_t>::max()};
    try { (void)asset_bytes(enormous); }
    catch (const std::overflow_error&) { overflow_rejected = true; }
    require(overflow_rejected, "runtime byte-size overflow is checked");

    std::cout << "generic_asset_pipeline_lab: all checks passed\n";
}
} // namespace allmight

int main() {
    try { allmight::run(); }
    catch (const std::exception& error) {
        std::cerr << "generic_asset_pipeline_lab failed: " << error.what() << '\n';
        return 1;
    }
}

