// An assert macro disappears under -DNDEBUG; this check never does.
void check(bool condition, const char* message) {
    if (!condition) throw std::runtime_error(message);
}

struct WorldSpace {};
struct ViewSpace {};
struct Meters {};
struct Seconds {};

// Deliberately restrictive: user-defined dual/autodiff scalars need a
// different concept that states and tests their required algebra.
template<class T>
concept RealScalar = std::floating_point<T>;

template<RealScalar T, std::size_t N, class Space>
struct Vector {
    using scalar_type = T;
    using space_type = Space;
    static constexpr std::size_t extent = N;
    std::array<T, N> coordinates{};
    constexpr T& operator[](std::size_t index) { return coordinates[index]; }
    constexpr T operator[](std::size_t index) const { return coordinates[index]; }
};
template<RealScalar T, std::size_t N, class Space>
constexpr Vector<T, N, Space> operator+(
    const Vector<T, N, Space>& a, const Vector<T, N, Space>& b) {
    Vector<T, N, Space> out{};
    for (std::size_t i = 0; i < N; ++i) out[i] = a[i] + b[i];
    return out;
}

template<RealScalar T, class Unit> struct Quantity { T value{}; };
template<RealScalar T, class Unit>
constexpr Quantity<T, Unit> operator+(
    Quantity<T, Unit> a, Quantity<T, Unit> b) {
    return {a.value + b.value};
}

// A small expression tree postpones materialization. Its references
// may dangle when operands or temporary child nodes are destroyed.
template<class E>
concept VectorExpression = requires(const E& expr, std::size_t i) {
    typename E::scalar_type;
    typename E::space_type;
    requires RealScalar<typename E::scalar_type>;
    { E::extent } -> std::convertible_to<std::size_t>;
    { expr[i] } -> std::same_as<typename E::scalar_type>;
};
template<class L, class R>
concept CompatibleExpressions = VectorExpression<L> && VectorExpression<R>
    && std::same_as<typename L::scalar_type, typename R::scalar_type>
    && std::same_as<typename L::space_type, typename R::space_type>
    && (L::extent == R::extent);

template<class L, class R> requires CompatibleExpressions<L, R>
struct SumExpr {
    using scalar_type = typename L::scalar_type;
    using space_type = typename L::space_type;
    static constexpr std::size_t extent = L::extent;
    const L& left;
    const R& right;
    constexpr auto operator[](std::size_t i) const {
        return left[i] + right[i];
    }
};
template<class L, class R> requires CompatibleExpressions<L, R>
constexpr SumExpr<L, R> lazy_add(const L& a, const R& b) {
    return {a, b};
}
template<RealScalar T, std::size_t N, class Space, VectorExpression Expr>
    requires std::same_as<T, typename Expr::scalar_type>
        && std::same_as<Space, typename Expr::space_type>
        && (N == Expr::extent)
constexpr Vector<T, N, Space> materialize(const Expr& expr) {
    Vector<T, N, Space> out{};
    for (std::size_t i = 0; i < N; ++i) out[i] = expr[i];
    return out;
}

// Runtime dimensions are not encoded in the type; check before access.
template<RealScalar T>
T dot_dynamic(std::span<const T> a, std::span<const T> b) {
    if (a.size() != b.size())
        throw std::invalid_argument("mismatched dimensions");
    T total{};
    for (std::size_t i = 0; i < a.size(); ++i)
        total += a[i] * b[i];
    return total;
}

// Intrusive storage keeps next/link state inside the client's Task object.
// The stack does not own Tasks. Linked tasks must outlive the stack and
// remain at the same address; destruction of the stack unlinks survivors.
struct Task {
    std::string name;
    Task* next{};
    bool linked{};
};
class IntrusiveTaskStack {
    Task* head_{};
public:
    IntrusiveTaskStack() = default;
    IntrusiveTaskStack(const IntrusiveTaskStack&) = delete;
    IntrusiveTaskStack& operator=(const IntrusiveTaskStack&) = delete;
    IntrusiveTaskStack(IntrusiveTaskStack&&) = delete;
    IntrusiveTaskStack& operator=(IntrusiveTaskStack&&) = delete;
    ~IntrusiveTaskStack() {
        while (pop()) {}
    }
    void push(Task& task) {
        if (task.linked) throw std::logic_error("task already linked");
        task.next = head_;
        task.linked = true;
        head_ = &task;
    }
    [[nodiscard]] Task* pop() noexcept {
        Task* task = head_;
        if (!task) return nullptr;
        head_ = task->next;
        task->next = nullptr;
        task->linked = false;
        return task;
    }
};

template<class L, class R>
concept CanLazyAdd = requires(const L& a, const R& b) { lazy_add(a, b); };
template<class T, std::size_t N, class Space, class Expr>
concept CanMaterialize = requires(const Expr& expr) {
    materialize<T, N, Space>(expr);
};

void test_handles_and_catalog() {
    AssetCatalog catalog;
    AssetCatalog another_catalog;

    const auto previous = catalog.insert({"teapot", 128});
    check(catalog.live_count() == 1, "live count");
    auto owned_snapshot = catalog.lookup(previous);
    check(owned_snapshot && owned_snapshot->name == "teapot", "initial lookup");

    // Grow the slot vector many times; the logical handle must survive
    // reallocations even though internal Slot addresses may change.
    for (unsigned i = 0; i < 128; ++i) {
        const auto extra = catalog.insert({"extra-" + std::to_string(i), 3});
        check(extra.catalog_id == previous.catalog_id, "stable catalog owner");
    }
    check(catalog.lookup(previous)->name == "teapot",
          "logical handle survives vector growth");
    check(catalog.erase(previous), "first erase");
    check(!catalog.lookup(previous), "stale generation rejected");
    check(owned_snapshot->name == "teapot", "owned copy survives erase");

    const auto replacement = catalog.insert({"terrain", 4096});
    check(replacement.slot == previous.slot, "slot reused");
    check(replacement.generation != previous.generation, "generation advanced");
    check(catalog.lookup(replacement)->vertex_count == 4096,
          "new content belongs to new generation");

    const auto foreign = another_catalog.insert({"other", 7});
    check(!catalog.lookup(foreign), "foreign catalog identity rejected");
    check(!another_catalog.lookup(replacement), "foreign identity rejected");

    AssetCatalog moved = std::move(catalog);
    check(moved.lookup(replacement).has_value(), "moved pool preserves identity");
    bool rejected = false;
    try { (void)catalog.live_count(); }
    catch (const std::logic_error&) { rejected = true; }
    check(rejected, "moved-from catalog rejects method call");
}

void test_generic_math_and_lifetimes() {
    using W3 = Vector<float, 3, WorldSpace>;
    using V3 = Vector<float, 3, ViewSpace>;
    using W2 = Vector<float, 2, WorldSpace>;
    using DW3 = Vector<double, 3, WorldSpace>;
    static_assert(!std::same_as<W3, V3>);
    static_assert(CanLazyAdd<W3, W3>);
    static_assert(!CanLazyAdd<W3, V3>);
    static_assert(!CanLazyAdd<W3, W2>);
    static_assert(!CanLazyAdd<W3, DW3>);
    using Sum = decltype(lazy_add(std::declval<const W3&>(),
                                 std::declval<const W3&>()));
    static_assert(CanMaterialize<float, 3, WorldSpace, Sum>);
    static_assert(!CanMaterialize<float, 3, ViewSpace, Sum>);
    static_assert(!CanMaterialize<float, 2, WorldSpace, Sum>);
    static_assert(!CanMaterialize<double, 3, WorldSpace, Sum>);
    using NestedSum = decltype(lazy_add(std::declval<const Sum&>(),
                                       std::declval<const W3&>()));
    static_assert(CanMaterialize<float, 3, WorldSpace, NestedSum>);
    static_assert(!CanLazyAdd<NestedSum, V3>);
    static_assert(!std::same_as<MeshHandle, TextureHandle>);
    static_assert(!std::same_as<Quantity<float, Meters>, Quantity<float, Seconds>>);
    static_assert(sizeof(W3) == 3 * sizeof(float));
    static_assert(RealScalar<double> && !RealScalar<int>);

    constexpr W3 a{{1, 2, 3}}, b{{4, 5, 6}}, c{{7, 8, 9}};
    constexpr auto eager = a + b + c;
    // Reference-bearing expression objects point to automatic locals;
    // do not require their addresses to be core constant expressions.
    const auto inner = lazy_add(a, b);
    const auto lazy = materialize<float, 3, WorldSpace>(lazy_add(inner, c));
    check(eager.coordinates == lazy.coordinates, "lazy and eager agree");
    static_assert(eager.coordinates == std::array<float, 3>{12, 15, 18});

    const std::array<double, 3> left{1, 2, 3}, right{4, 5, 6};
    const std::array<double, 2> short_right{3, 4};
    check(dot_dynamic<double>(left, right) == 32, "dynamic dot result");
    bool mismatch = false;
    try { (void)dot_dynamic<double>(left, short_right); }
    catch (const std::invalid_argument&) { mismatch = true; }
    check(mismatch, "dynamic length mismatch rejected");
}

void test_intrusive_versus_owning() {
    static_assert(!std::is_copy_constructible_v<IntrusiveTaskStack>);
    static_assert(!std::is_copy_assignable_v<IntrusiveTaskStack>);
    static_assert(!std::is_move_constructible_v<IntrusiveTaskStack>);
    static_assert(!std::is_move_assignable_v<IntrusiveTaskStack>);
    Task upload{"upload"}, render{"render"};
    IntrusiveTaskStack queue;
    queue.push(upload);
    queue.push(render);

    bool duplicate = false;
    try { queue.push(upload); }
    catch (const std::logic_error&) { duplicate = true; }
    check(duplicate, "cannot link an intrusive node twice");

    check(queue.pop() == &render, "intrusive order");
    check(queue.pop() == &upload, "intrusive next");
    check(queue.pop() == nullptr, "empty stack");
    check(!upload.linked && !render.linked, "unlink clears membership");

    // Nodes precede the nested stack, so they survive its destructor.
    {
        IntrusiveTaskStack temporary;
        temporary.push(upload);
        temporary.push(render);
    }
    check(!upload.linked && !render.linked && !upload.next && !render.next,
          "stack destruction unlinks surviving nodes");
    queue.push(upload);
    check(queue.pop() == &upload, "unlinked node can join another stack");

    // This separately allocated container OWNS string values, unlike the
    // intrusive stack. No performance comparison is inferred.
    std::forward_list<std::string> owned{"upload", "render"};
    check(*owned.begin() == "upload", "non-intrusive owned element");
}
} // namespace

int main() {
    try {
        test_handles_and_catalog();
        test_generic_math_and_lifetimes();
        test_intrusive_versus_owning();
        std::cout << "m018: PIMPL/handles/typed math/lifetimes: PASS\n";
    } catch (const std::exception& e) {
        std::cerr << "m018: FAIL: " << e.what() << '\n';
        return 1;
    }
    return 0;
}

// Mathematics continuous-note C++20 first-contact oracle; code and tested source stay identical.
#include <cmath>
#include <iostream>
#include <optional>
#include <stdexcept>
struct Vec2 { double x{}, y{}; };
struct Disk2 { Vec2 centre{}, velocity{}; double radius{}; };
double dot(Vec2 a, Vec2 b) { return a.x*b.x+a.y*b.y; }

std::optional<double> firstTouch(Disk2 a, Disk2 b, double h) {
    const auto valid = [](Disk2 d) {
        return std::isfinite(d.centre.x)&&std::isfinite(d.centre.y)&&
               std::isfinite(d.velocity.x)&&std::isfinite(d.velocity.y)&&
               std::isfinite(d.radius)&&d.radius>0;
    };
    if (!valid(a)||!valid(b)||!std::isfinite(h)||h<0)
        throw std::invalid_argument("invalid disk or horizon");
    Vec2 p{b.centre.x-a.centre.x,b.centre.y-a.centre.y};
    Vec2 v{b.velocity.x-a.velocity.x,b.velocity.y-a.velocity.y};
    const double R=a.radius+b.radius;
    const double aa=dot(v,v),bb=2*dot(p,v),cc=dot(p,p)-R*R;
    if (!std::isfinite(aa)||!std::isfinite(bb)||!std::isfinite(cc))
        throw std::overflow_error("nonfinite collision coefficients");
    if (cc<0) throw std::domain_error("existing overlap");
    if (cc==0) return 0.0; // Touching, not automatically a new impact.
    if (aa==0||bb>=0) return std::nullopt;
    const double discriminant=std::fma(bb,bb,-4*aa*cc);
    if (!std::isfinite(discriminant))
        throw std::overflow_error("discriminant overflow");
    if (discriminant<0) return std::nullopt;
    const double q=-0.5*(bb-std::sqrt(discriminant));
    if (!(q>0)) return std::nullopt;
    const double t=cc/q;
    if (!std::isfinite(t)||t<0||t>h) return std::nullopt;
    return t;
}
int main() {
    auto near=[](double actual,double expected) {
        if (!std::isfinite(actual)||std::abs(actual-expected)>1e-10)
            throw std::runtime_error("unexpected first-contact time");
    };
    const Disk2 fixed{{0,0},{0,0},1};
    const Disk2 moving{{10,0},{-100,0},1};
    const auto impact=firstTouch(fixed,moving,0.1);
    if (!impact) throw std::runtime_error("fast contact was missed");
    near(*impact,0.08);
    if (firstTouch(fixed,moving,0.05))
        throw std::runtime_error("collision outside horizon was accepted");
    if (firstTouch(fixed,{{10,0},{100,0},1},1.0))
        throw std::runtime_error("separating disks reported impact");
    if (firstTouch(fixed,{{10,0},{0,0},1},1.0))
        throw std::runtime_error("static separated disks reported impact");
    if (firstTouch(fixed,{{10,2.1},{-10,0},1},2.0))
        throw std::runtime_error("geometric near miss reported impact");
    const auto tangent=firstTouch(fixed,{{10,2},{-10,0},1},2.0);
    if (!tangent) throw std::runtime_error("tangency not found");
    near(*tangent,1.0);
    const auto galilean=firstTouch({{0,0},{55,7},1},
                                   {{10,0},{-45,7},1},0.1);
    if (!galilean) throw std::runtime_error("relative motion invariance failed");
    near(*galilean,0.08);
    bool rejected=false;
    try { (void)firstTouch(fixed,{{1,0},{0,0},1},1); }
    catch(const std::domain_error&) { rejected=true; }
    if (!rejected) throw std::runtime_error("initial overlap not rejected");
    rejected=false;
    try { (void)firstTouch(fixed,moving,-1); }
    catch(const std::invalid_argument&) { rejected=true; }
    if (!rejected) throw std::runtime_error("negative time accepted");
    std::cout<<"math first contact: entry, no-hit, tangency, invariance and validation PASS\n";
}

// C++20 sequential-impulse witness. Normal points A->B; units: m, s, kg, radians.
// Build: c++ -std=c++20 -O2 -Wall -Wextra -Wpedantic -Werror tools/labs/persistent_contact_lab.cpp -o /tmp/persistent_contact && /tmp/persistent_contact
#include <algorithm>
#include <cmath>
#include <cstdint>
#include <iostream>
#include <limits>
#include <stdexcept>
#include <vector>
struct Vec2 { double x{},y{}; };
constexpr Vec2 operator+(Vec2 a,Vec2 b){return {a.x+b.x,a.y+b.y};}
constexpr Vec2 operator-(Vec2 a,Vec2 b){return {a.x-b.x,a.y-b.y};}
constexpr Vec2 operator*(Vec2 a,double k){return {a.x*k,a.y*k};}
constexpr double dot(Vec2 a,Vec2 b){return a.x*b.x+a.y*b.y;}
constexpr double cross(Vec2 a,Vec2 b){return a.x*b.y-a.y*b.x;}
constexpr Vec2 spin(double w,Vec2 r){return {-w*r.y,w*r.x};}
void ensure(bool p,const char* s){if(!p)throw std::runtime_error(s);}
void near(double a,double b,double eps=1e-9){
 if(!(std::isfinite(a)&&std::isfinite(b)&&std::abs(a-b)<=eps))
  throw std::runtime_error("unexpected numerical result");
}
void validate(Vec2 v){ensure(std::isfinite(v.x)&&std::isfinite(v.y),"nonfinite vector");}
struct Body{Vec2 center{},linear{};double omega{},invMass{},invInertia{};};
void validate(const Body& b){
 validate(b.center);validate(b.linear);
 ensure(std::isfinite(b.omega)&&std::isfinite(b.invMass)&&std::isfinite(b.invInertia),"nonfinite body");
 ensure(b.invMass>=0&&b.invInertia>=0,"negative inverse mass/inertia");
}
struct Contact{
 std::uint64_t featureId{}; // Cache valid only while bodies, feature and orientation match.
 Vec2 worldPoint{},normal{0,1};
 double friction{},restitution{},normalImpulse{},tangentImpulse{},targetNormalSpeed{};
};
Vec2 unit(Vec2 v){
 validate(v);const double m=std::hypot(v.x,v.y);
 ensure(std::isfinite(m)&&m>std::numeric_limits<double>::min(),"invalid normal");
 return v*(1/m);
}
void validate(const Contact& c){
 validate(c.worldPoint);validate(c.normal);
 ensure(std::isfinite(c.friction)&&c.friction>=0&&std::isfinite(c.restitution)
  &&c.restitution>=0&&c.restitution<=1,"invalid material");
 ensure(std::isfinite(c.normalImpulse)&&c.normalImpulse>=0
  &&std::isfinite(c.tangentImpulse)&&std::isfinite(c.targetNormalSpeed),"invalid impulse cache");
}
struct Row{Body* a{};Body* b{};Contact* c{};Vec2 ra{},rb{},n{},t{};double kn{},kt{};};
Vec2 relative_velocity(const Row& r){
 return r.b->linear+spin(r.b->omega,r.rb)-r.a->linear-spin(r.a->omega,r.ra);
}
double inverse_effective_mass(const Row& r,Vec2 d){
 const double ca=cross(r.ra,d),cb=cross(r.rb,d);
 return r.a->invMass+r.b->invMass+r.a->invInertia*ca*ca+r.b->invInertia*cb*cb;
}
void apply(const Row& r,Vec2 p){
 r.a->linear=r.a->linear-p*r.a->invMass;
 r.b->linear=r.b->linear+p*r.b->invMass;
 r.a->omega-=r.a->invInertia*cross(r.ra,p);
 r.b->omega+=r.b->invInertia*cross(r.rb,p);
}
Row make_row(Body& a,Body& b,Contact& c,double threshold=0.5,bool newImpact=true){
 validate(a);validate(b);validate(c);
 ensure(std::isfinite(threshold)&&threshold>=0,"invalid bounce threshold");
 Row r{&a,&b,&c,c.worldPoint-a.center,c.worldPoint-b.center,unit(c.normal)};
 r.t={-r.n.y,r.n.x};
 r.kn=inverse_effective_mass(r,r.n);r.kt=inverse_effective_mass(r,r.t);
 ensure(std::isfinite(r.kn)&&std::isfinite(r.kt)&&r.kn>=0&&r.kt>=0,"invalid effective mass");
 // Sample and freeze restitution before applying impulses. No new bounce on persistent rest contact.
 if(newImpact){
  const double vn=dot(relative_velocity(r),r.n);
  c.targetNormalSpeed=vn< -threshold?-c.restitution*vn:0;
 }else c.targetNormalSpeed=0;
 ensure(std::abs(c.tangentImpulse)<=c.friction*c.normalImpulse+1e-9,"invalid friction cache");
 return r;
}
void warm_start(const Row& r){
 if(r.kn>0)apply(r,r.n*r.c->normalImpulse+r.t*r.c->tangentImpulse);
}
void solve_one(const Row& r){
 if(r.kn==0)return; // static/static, or locked in this direction
 Contact& c=*r.c;
 const double vn=dot(relative_velocity(r),r.n),oldN=c.normalImpulse;
 c.normalImpulse=std::max(0.0,oldN+(c.targetNormalSpeed-vn)/r.kn);
 apply(r,r.n*(c.normalImpulse-oldN));
 if(r.kt==0)return;
 const double vt=dot(relative_velocity(r),r.t),oldT=c.tangentImpulse;
 const double frictionBound=c.friction*c.normalImpulse;
 c.tangentImpulse=std::clamp(oldT-vt/r.kt,-frictionBound,frictionBound);
 apply(r,r.t*(c.tangentImpulse-oldT));
}
void sweep(std::vector<Row>& rows,int iterations){
 ensure(iterations>=0&&iterations<=10000,"invalid iteration count");
 for(int i=0;i<iterations;++i)for(const Row& r:rows)solve_one(r);
}
int main(){
 { // Equal masses: coefficient of restitution one conserves kinetic energy and momentum.
  Body a{{0,0},{2,0},0,1,1},b{{1,0},{0,0},0,1,1};
  Contact c{11,{0.5,0},{1,0},0,1};
  Row r=make_row(a,b,c);std::vector<Row> rows{r};sweep(rows,8);
  near(a.linear.x,0);near(b.linear.x,2);near(c.normalImpulse,2);
  near(a.linear.x+b.linear.x,2);near((dot(a.linear,a.linear)+dot(b.linear,b.linear))/2,2);
  sweep(rows,8);near(c.normalImpulse,2); // Restitution target was not regenerated.
 }
 { // Tangent = (-1,0) for upward normal; +1 tangent impulse opposes +x sliding.
  Body ground{{0,0},{0,0},0,0,0},box{{0,1},{3,-2},0,1,1};
  Contact c{12,{0,1},{0,1},0.5,0};
  Row r=make_row(ground,box,c);std::vector<Row> rows{r};sweep(rows,5);
  near(box.linear.y,0);near(box.linear.x,2);
  near(c.normalImpulse,2);near(c.tangentImpulse,1);
 }
 { // Off-center normal impulse produces angular velocity through r cross P.
  Body wall{{0,0},{0,0},0,0,0},box{{1,0},{-2,0},0,1,1};
  Contact c{13,{1,1},{1,0},0,0};
  Row r=make_row(wall,box,c);std::vector<Row> rows{r};sweep(rows,8);
  near(box.linear.x,-1);near(box.omega,-1);
 }
 { // Separating velocity and zero effective mass cannot generate attractive impulse.
  Body a{{0,0},{1,0},0,1,1},b{{1,0},{2,0},0,1,1};
  Contact c{14,{0.5,0},{1,0},0,0};
  Row r=make_row(a,b,c);std::vector<Row> rows{r};sweep(rows,2);
  near(c.normalImpulse,0);near(a.linear.x,1);near(b.linear.x,2);
  a.invMass=a.invInertia=b.invMass=b.invInertia=0;
  rows={make_row(a,b,c)};sweep(rows,2);near(c.normalImpulse,0);
 }
 { // Coupled two-point manifold, then warm-start with the preserved feature cache.
  Body ground{{0,0},{0,0},0,0,0},box{{0,1},{0,-2},0,1,1};
  Contact left{15,{-1,1},{0,1},0,0},right{16,{1,1},{0,1},0,0};
  std::vector<Row> rows{make_row(ground,box,left),make_row(ground,box,right)};
  sweep(rows,20);near(box.linear.y,0,1e-6);near(box.omega,0,1e-6);
  ensure(left.normalImpulse>=0&&right.normalImpulse>=0,"unilateral impulse");
  // Rebuilt velocities are *pre-warm-start*, otherwise the cached impulse is double-applied.
  box.linear={0,-2};box.omega=0;
  Row l=make_row(ground,box,left,0.5,false),r=make_row(ground,box,right,0.5,false);
  warm_start(l);warm_start(r);rows={l,r};sweep(rows,20);
  near(box.linear.y,0,1e-6);near(box.omega,0,1e-6);
 }
 { // A corrupted normal or NaN friction must be rejected rather than poison an island.
  Body a{},b{};Contact bad{17,{0,0},{0,0},0,0};bool rejected=false;
  try{(void)make_row(a,b,bad);}catch(const std::runtime_error&){rejected=true;}
  ensure(rejected,"zero normal accepted");bad.normal={1,0};
  bad.friction=std::numeric_limits<double>::quiet_NaN();rejected=false;
  try{(void)make_row(a,b,bad);}catch(const std::runtime_error&){rejected=true;}
  ensure(rejected,"NaN friction accepted");
 }
 std::cout<<"persistent-contact witness: 6 suites PASS\n";
}

// M163-M164 (2701-2744): a scoped deterministic 6502/NROM CPU-bus oracle.
// NOT a full NES: missing most opcodes, PPU rendering, APU, cycle-accurate
// bus traffic, DMC/real DMA arbitration, all other mappers and ROM timings.
#include <algorithm>
#include <array>
#include <cstddef>
